def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, worst

    def holds(cond):
        def predicate(row):
            inputs = row.get('inputs', {})
            outputs = row.get('outputs', {})
            return all(
                outputs.get(port, inputs.get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def any_condition(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    aborts = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    scl_changes = edges(trace, 'scl_oen', 'change')
    sda_changes = edges(trace, 'sda_oen', 'change')
    control_change = lambda row: (
        row.get('edge') in scl_changes or
        row.get('edge') in sda_changes
    )

    verdicts = []
    for probe in (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    ):
        sequence_rises = edges(trace, probe, 'rise')
        windows = after(
            trace,
            lambda row, rises=sequence_rises, p=probe: (
                row.get('edge') in rises and
                row.get('outputs', {}).get(p) == 1 and
                row.get('inputs', {}).get('ena') == 1
            ),
            until=holds({'cmd_ack': 1}),
            aborts=aborts,
        )
        verdicts.extend(
            eventually(
                window,
                control_change,
                strong=False,
                after_activation=True,
            )
            for window in windows
        )

    return worst(verdicts)

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def rising(port, i):
        return bool(out(trace[i], port)) and (i == 0 or not bool(out(trace[i - 1], port)))

    def reset(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    sequences = (
        ('start_sequence', 'START'),
        ('stop_sequence', 'STOP'),
        ('write_sequence', 'WRITE'),
        ('read_sequence', 'READ'),
    )
    starts = []
    for probe, label in sequences:
        for i, row in enumerate(trace):
            if (rising(probe, i) and inp(row, 'ena') == 1
                    and not reset(row) and not out(row, 'al')):
                starts.append((i, probe, label))
    starts.sort(key=lambda item: item[0])

    if not starts:
        return (None, None, 'no enabled supported command sequence occurred in this trace')

    verdicts = []
    for n, (start, probe, label) in enumerate(starts):
        next_start = starts[n + 1][0] if n + 1 < len(starts) else len(trace)
        ack = None
        arbitration_loss = None
        aborted = False

        for i in range(start, next_start):
            row = trace[i]
            if reset(row):
                aborted = True
                break
            if out(row, 'al') and (i == start or not out(trace[i - 1], 'al')):
                arbitration_loss = i
                break
            if out(row, 'cmd_ack') and (i == start or not out(trace[i - 1], 'cmd_ack')):
                ack = i
                break

        if aborted:
            verdicts.append((None, trace[start].get('edge'),
                             label + ' command was reset-aborted; no response was owed'))
        elif arbitration_loss is not None:
            verdicts.append((True, trace[arbitration_loss].get('edge'),
                             label + ' command reported arbitration loss through al'))
        elif ack is not None:
            verdicts.append((True, trace[ack].get('edge'),
                             label + ' command completed with cmd_ack'))
        else:
            verdicts.append((None, trace[start].get('edge'),
                             label + ' command began but the trace ended before completion or arbitration loss'))

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return verdicts[-1]

def decide(trace):
    if not trace:
        return (None, None, 'no sampled state for the open-drain requirement')

    for row in trace:
        outputs = row.get('outputs', {})
        if outputs.get('scl_o') != 0:
            return (False, row.get('edge'), 'scl_o is not constant low as required for the open-drain SCL drive value')
        if outputs.get('sda_o') != 0:
            return (False, row.get('edge'), 'sda_o is not constant low as required for the open-drain SDA drive value')

    return (True, None, 'scl_o and sda_o remained constant-low open-drain drive values')

def decide(trace):
    if not trace:
        return (None, None, 'no clock-edge observation occurred in this trace')

    for row in trace:
        outputs = row['outputs']
        bad = [port for port in ('scl_o', 'sda_o')
               if outputs.get(port) != 0]
        if bad:
            return (False, row['edge'],
                    f"{', '.join(bad)} must be constantly low")

        # In the declared READ sampling window SCL is released.  With an
        # active-low output-enable, release must therefore be scl_oen == 1.
        if outputs.get('read_sample_window') == 1 and outputs.get('scl_oen') != 1:
            return (False, row['edge'],
                    'scl_oen must be 1 when the READ sample window releases SCL')

        # The stable high phase of a WRITE bit has released SCL.
        if outputs.get('write_stable_high_phase') == 1:
            if outputs.get('scl_oen') != 1:
                return (False, row['edge'],
                        'scl_oen must be 1 during the released SCL-high WRITE phase')

            # A WRITE drives SDA low for din == 0 and releases it for
            # din == 1; active-low polarity therefore makes sda_oen == din.
            if outputs.get('sda_oen') != row['inputs'].get('din'):
                return (False, row['edge'],
                        'sda_oen must be 0 for din=0 (drive low) and 1 for din=1 (release) during the WRITE high phase')

    return (True, None,
            'scl_o and sda_o were low throughout; declared release phases also exhibited active-low output-enable polarity')

def decide(trace):
    from specflow.refmodel.temporal import edges, worst

    verdicts = []
    for port in ("scl_oen", "sda_oen"):
        changed = edges(trace, port, "change")
        rows = [r for r in trace if r["edge"] in changed]
        if not rows:
            verdicts.append((None, None, port + " did not change; no drive or release action occurred"))
            continue

        for row in rows:
            value = row["outputs"].get(port)
            if value not in (0, 1):
                verdicts.append((False, row["edge"],
                                 f"{port} became {value!r}; expected 0 for drive-low or 1 for release"))
            else:
                verdicts.append((True, row["edge"],
                                 f"{port} is {value} at its drive/release transition"))

    return worst(verdicts)

from specflow.refmodel.temporal import TO_END, after, eventually, worst

def decide(trace):
    commands = (1, 2, 4, 8)
    line_ports = ("scl_o", "scl_oen", "sda_o", "sda_oen")

    def supported(row):
        return row.get("inputs", {}).get("cmd") in commands

    def line_state(row):
        outputs = row.get("outputs", {})
        return tuple(outputs.get(port) for port in line_ports)

    def line_changed_from_activation(row, window):
        return line_state(row) != tuple(window.value(port) for port in line_ports)

    windows = after(trace, supported, until=TO_END)
    return worst([
        eventually(
            window,
            lambda row, w=window: line_changed_from_activation(row, w),
            strong=True,
            after_activation=True,
        )
        for window in windows
    ])

def decide(trace):
    reset_values = {
        'al': 0,
        'busy': 0,
        'cmd_ack': 0,
        'scl_oen': 1,
        'sda_oen': 1,
    }

    activations = [
        row for row in trace
        if row.get('inputs', {}).get('rst') == 1
    ]

    if not activations:
        return (None, None, 'the synchronous rst reset condition never occurred')

    for row in activations:
        outputs = row.get('outputs', {})
        bad = [
            port for port, value in reset_values.items()
            if outputs.get(port) != value
        ]
        if bad:
            return (
                False,
                row.get('edge'),
                'on the rising edge with synchronous rst asserted, expected '
                'al=0, busy=0, cmd_ack=0, scl_oen=1, and sda_oen=1; '
                'incorrect ports: ' + ', '.join(bad)
            )

    return (
        True,
        activations[0].get('edge'),
        'each observed rising edge with synchronous rst asserted had cleared '
        'bus-status and acknowledge outputs and released both output enables'
    )

def decide(trace):
    reset_edges = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]['inputs'].get('nReset')
        current = trace[i]['inputs'].get('nReset')
        if previous == 1 and current == 0:
            reset_edges.append(i)

    if not reset_edges:
        return (None, None, 'nReset was never asserted low in this trace')

    expected = {
        'cmd_ack': 0,
        'busy': 0,
        'al': 0,
        'dout': 0,
        'scl_oen': 1,
        'sda_oen': 1,
    }

    for i in reset_edges:
        row = trace[i]
        bad = [
            '%s=%r, expected %r' % (port, row['outputs'].get(port), value)
            for port, value in expected.items()
            if row['outputs'].get(port) != value
        ]
        if bad:
            return (False, row['edge'],
                    'after nReset asserted low, reset state was not initialized asynchronously: '
                    + '; '.join(bad))

    return (True, trace[reset_edges[0]]['edge'],
            'nReset assertion asynchronously initialized the declared resettable outputs '
            'without requiring a clock transition')

from specflow.refmodel.temporal import TO_END, after, edges, stable, worst

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def active_disabled(row):
        return (inp(row, 'ena') == 0 and
                out(row, 'active_command') == 1)

    def command_done_or_aborted(row):
        return (inp(row, 'ena') != 0 or
                out(row, 'active_command') != 1)

    scl_windows = after(
        trace,
        active_disabled,
        until=command_done_or_aborted
    )

    # The route describes a stable START- or STOP-shaped transition while
    # ena is low.  Use the actual input transition as the trigger, rather than
    # the held line level, so an already-stable bus does not create a false
    # filtering window.
    sda_fall = edges(trace, 'sda_i', 'fall')
    sda_rise = edges(trace, 'sda_i', 'rise')

    def filtered_transition_window(row):
        if inp(row, 'ena') != 0 or inp(row, 'scl_i') != 1:
            return False
        if row.get('edge') in sda_fall or row.get('edge') in sda_rise:
            return True
        return False

    def transition_window_ends(row):
        return inp(row, 'ena') != 0 or inp(row, 'scl_i') != 1

    busy_windows = after(
        trace,
        filtered_transition_window,
        until=transition_window_ends
    )

    ordinary_progress = any(
        i > 0 and
        inp(trace[i - 1], 'ena') != 0 and
        inp(trace[i], 'ena') != 0 and
        out(trace[i - 1], 'active_command') == 1 and
        out(trace[i], 'active_command') == 1 and
        out(trace[i - 1], 'scl_oen') != out(trace[i], 'scl_oen')
        for i in range(len(trace))
    )

    if not scl_windows and not busy_windows:
        return (None, None, 'no ena-low timing or START/STOP-shaped filter window was observed')

    if not ordinary_progress:
        return (None, None, 'ena-high ordinary SCL-phase progress was not observed for route comparison')

    verdicts = []
    verdicts.extend(stable(w, 'scl_oen') for w in scl_windows)
    verdicts.extend(stable(w, 'busy') for w in busy_windows)
    return worst(verdicts)

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    # No authoritative cmd encoding table is supplied.  Use the declared
    # START-sequence probe as the port-level signature of decoding START.
    starts = []
    for i, row in enumerate(trace):
        if reset_active(row):
            continue
        was_start = i > 0 and out(trace[i - 1], 'start_sequence') == 1
        if out(row, 'start_sequence') == 1 and not was_start:
            if i == 0 or out(trace[i - 1], 'idle') == 1:
                starts.append(i)

    if not starts:
        return (None, None,
                'START command situation never occurred; no numeric cmd encoding was assumed')

    for start in starts:
        for i in range(start, len(trace)):
            row = trace[i]
            if reset_active(row):
                return (None, row['edge'],
                        'START decoding attempt was aborted by reset')

            previous = trace[i - 1] if i > 0 else None
            if (previous is not None and
                    out(previous, 'sda_oen') == 1 and
                    out(row, 'sda_oen') == 0 and
                    out(row, 'scl_oen') == 1):
                return (True, row['edge'],
                        'START decoding produced the licensed sda_oen 1-to-0 transition while scl_oen remained released')

            if i > start and out(row, 'start_sequence') != 1:
                return (False, row['edge'],
                        'START sequence ended without the licensed sda_oen transition while scl_oen was released')

    return (None, trace[-1]['edge'],
            'START command situation occurred but the trace ended before its routed transition was observable')

def decide(trace):
    from specflow.refmodel.temporal import after, pulse, worst

    def holds(cond):
        def predicate(row):
            values = dict(row.get('inputs', {}))
            values.update(row.get('outputs', {}))
            return all(values.get(port) == value for port, value in cond.items())
        return predicate

    def aborts(row):
        return row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1

    windows = after(
        trace,
        holds({'stop_sequence': 1}),
        until=holds({'idle': 1}),
        aborts=aborts,
    )
    return worst([
        pulse(w, 'cmd_ack', width=1, active=1, after_activation=True)
        for w in windows
    ])

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst

    def is_write(row):
        return row['outputs'].get('write_sequence') == 1 and row['inputs'].get('ena') == 1

    def write_done(row):
        return row['outputs'].get('write_sequence') != 1

    windows = after(trace, is_write, until=write_done)

    def follows_din(row):
        din = row['inputs'].get('din')
        expected = 0 if din == 0 else 1
        return row['outputs'].get('sda_oen') == expected

    return worst([
        throughout(w, follows_din, after_activation=False)
        for w in windows
    ])

from specflow.refmodel.temporal import after, throughout, worst

def decide(trace):
    unsupported_or_idle = {
        0, 3, 5, 6, 7, 9, 10, 11, 12, 13, 14, 15
    }

    def idle_with_unsupported_cmd(row):
        return (
            row['outputs'].get('idle') == 1
            and row['inputs'].get('cmd') in unsupported_or_idle
        )

    def unsupported_cmd_ends(row):
        return row['inputs'].get('cmd') not in unsupported_or_idle

    windows = after(
        trace,
        idle_with_unsupported_cmd,
        until=unsupported_cmd_ends
    )

    return worst([
        throughout(
            window,
            lambda row: row['outputs'].get('idle') == 1,
            after_activation=False
        )
        for window in windows
    ])

from specflow.refmodel.temporal import after, throughout, TO_END, worst

def decide(trace):
    def active(row):
        return (
            row['inputs'].get('cmd') == 4 and
            row['inputs'].get('ena') == 1 and
            row['outputs'].get('write_sequence') == 1
        )

    def aborts(row):
        return (
            row['outputs'].get('al') == 1 or
            row['inputs'].get('nReset') == 0 or
            row['inputs'].get('rst') == 1
        )

    windows = after(
        trace,
        active,
        until=lambda r: r['outputs'].get('cmd_ack') == 1,
        aborts=aborts
    )

    return worst([
        throughout(
            w,
            lambda r, value=w.value('din'): r['outputs'].get('sda_oen') == value,
            after_activation=True
        )
        for w in windows
    ])

from specflow.refmodel.temporal import after, edges, eventually, throughout, worst


def decide(trace):
    def any_condition(conditions):
        def predicate(row):
            return any(
                all(row['outputs'].get(port, row['inputs'].get(port)) == value
                    for port, value in condition.items())
                for condition in conditions
            )
        return predicate

    # write_sequence is the declared signature of the WRITE situation.
    # Use its rising transition so an initially released sda_oen value in
    # reset/idle is not mistaken for WRITE data-drive behaviour.
    write_start_edges = edges(trace, 'write_sequence', 'rise')
    applies = lambda row: (
        row['edge'] in write_start_edges and
        row['inputs'].get('ena') == 1 and
        row['inputs'].get('din') in (0, 1)
    )

    windows = after(
        trace,
        applies,
        until=any_condition([{'cmd_ack': 1}]),
        aborts=any_condition([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1}
        ])
    )

    def required_enable(window):
        expected = 0 if window.value('din') == 0 else 1
        return throughout(
            window,
            lambda row: row['outputs'].get('sda_oen') == expected,
            after_activation=True
        )

    return worst([required_enable(window) for window in windows])

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def active(row):
        return inp(row, 'nReset') == 1 and inp(row, 'rst') == 0 and inp(row, 'ena') == 1

    checked = False
    first_edge = None

    # A raw SDA transition must not immediately affect START/STOP status
    # unless the filtered detector has reported the corresponding condition.
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        if not active(row) or not active(prev):
            continue
        raw_changed = inp(row, 'sda_i') != inp(prev, 'sda_i')
        filtered_unchanged = out(row, 'ssda') == out(prev, 'ssda')
        no_filtered_condition = not (out(row, 'sta_condition') or out(row, 'sto_condition'))
        if raw_changed and filtered_unchanged and no_filtered_condition:
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if out(row, 'busy') != out(prev, 'busy'):
                return (False, row['edge'],
                        'busy changed from raw sda_i before the SDA transition was synchronized and filtered')

    # A detected START/STOP condition is the filtered observation used by busy.
    for i, row in enumerate(trace):
        if not active(row):
            continue
        if out(row, 'sta_condition'):
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if any(out(r, 'busy') == 1 for r in trace[i:]):
                continue
            return (None, row['edge'],
                    'filtered START was detected, but the trace ended before busy evidence appeared')
        if out(row, 'sto_condition'):
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if any(out(r, 'busy') == 0 for r in trace[i:]):
                continue
            return (None, row['edge'],
                    'filtered STOP was detected, but the trace ended before busy evidence appeared')

    # Arbitration must use the filtered SDA value during the declared
    # stable-high WRITE checking situation, not the raw input.
    for i, row in enumerate(trace):
        if not active(row):
            continue
        write_high = (out(row, 'write_stable_high') == 1 or
                      out(row, 'sda_chk') == 1)
        if write_high and out(row, 'sda_oen') == 1 and out(row, 'ssda') == 0:
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if any(out(r, 'al') == 1 for r in trace[i:]):
                continue
            return (None, row['edge'],
                    'filtered SDA indicated arbitration loss, but the trace ended before al asserted')
        if write_high and out(row, 'sda_oen') == 1 and out(row, 'ssda') == 1 and inp(row, 'sda_i') == 0:
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if out(row, 'al') == 1:
                return (False, row['edge'],
                        'al asserted from raw low sda_i while synchronized and filtered SDA was high')

    # At a filtered SCL rising edge in the declared READ sampling window,
    # dout must reflect the filtered SDA value.
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        if not active(row):
            continue
        filtered_scl_rise = out(prev, 'sscl') == 0 and out(row, 'sscl') == 1
        if filtered_scl_rise and out(row, 'read_sample_window') == 1:
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if out(row, 'dout') != out(row, 'ssda'):
                return (False, row['edge'],
                        'dout did not capture the synchronized and filtered SDA value at the filtered SCL rising edge')

    if not checked:
        return (None, None, 'the trace contains no applicable synchronized/filtered SDA observation')
    return (True, first_edge, 'SDA observations used by busy, al, and dout are qualified by synchronized and filtered signals')

def decide(trace):
    sequence_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def value(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def normal_completion(row):
        return (
            value(row, 'idle') == 1
            and row.get('inputs', {}).get('ena') == 1
            and row.get('inputs', {}).get('rst') != 1
            and row.get('inputs', {}).get('nReset') != 0
            and value(row, 'al') != 1
        )

    finishes = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]
        current = trace[i]
        was_in_sequence = any(value(previous, probe) == 1
                              for probe in sequence_probes)
        is_out_of_sequence = not any(value(current, probe) == 1
                                     for probe in sequence_probes)
        if was_in_sequence and is_out_of_sequence and normal_completion(current):
            finishes.append(i)

    if not finishes:
        return (None, None,
                'no normal START, STOP, READ, or WRITE command completion occurred')

    for i in finishes:
        row = trace[i]
        edge = row.get('edge')
        if value(row, 'cmd_ack') != 1:
            return (False, edge,
                    'cmd_ack was not asserted when the normal command completed')

        high_edges = 0
        j = i
        while j < len(trace) and value(trace[j], 'cmd_ack') == 1:
            high_edges += trace[j].get('held', 0)
            j += 1

        if high_edges != 1:
            return (False, edge,
                    f'cmd_ack was high for {high_edges} edges; expected exactly one clock cycle')

        if j == len(trace):
            return (None, edge,
                    'cmd_ack was high for one observed edge, but deassertion was not observed before the trace ended')

    return (True, None,
            f'{len(finishes)} normal command completion acknowledge pulse(s) were each exactly one clock cycle')

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def aborted(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1 or
                out(row, 'al') == 1)

    completions = []
    for i in range(1, len(trace)):
        before = out(trace[i - 1], 'active_command')
        now = out(trace[i], 'active_command')
        if before == 1 and now == 0:
            completions.append(i)

    verdicts = []
    for start in completions:
        if aborted(trace[start]):
            continue

        end = len(trace)
        for j in range(start + 1, len(trace)):
            if (out(trace[j - 1], 'active_command') == 0 and
                    out(trace[j], 'active_command') == 1):
                end = j
                break

        high_runs = []
        run_rows = []
        voided = False
        for j in range(start, end):
            row = trace[j]
            if not run_rows and aborted(row):
                voided = True
                break
            if out(row, 'cmd_ack') == 1:
                run_rows.append(row)
            elif run_rows:
                high_runs.append(run_rows)
                run_rows = []
        if run_rows:
            high_runs.append(run_rows)

        if voided:
            continue

        if not high_runs:
            verdicts.append((False, trace[start].get('edge'),
                             'cmd_ack was not asserted when the bit-level command finished'))
            continue

        if len(high_runs) != 1:
            verdicts.append((False, high_runs[0][0].get('edge'),
                             'cmd_ack was asserted in more than one pulse when the command finished'))
            continue

        pulse = high_runs[0]
        width = sum(row.get('held', 0) for row in pulse)
        if width != 1:
            verdicts.append((False, pulse[0].get('edge'),
                             f'cmd_ack was asserted for {width} clock edges, expected exactly one clk cycle'))
        else:
            verdicts.append((True, pulse[0].get('edge'),
                             'cmd_ack was asserted for exactly one clk cycle when the command finished'))

    if not verdicts:
        return (None, None, 'the command-completion activation never occurred')
    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    return verdicts[0]

