    arbitration_lost = _holds({"al": 1})

    def aborted(row):
        return reset(row) or sync_reset(row) or arbitration_lost(row)

    start_edges = edges(trace, "sta_condition", "rise")
    stop_edges = edges(trace, "sto_condition", "rise")

    start_windows = after(
        trace,
        lambda row: row["edge"] in start_edges
                    and row.get("inputs", {}).get("ena") == 1,
        until=_holds({"sto_condition": 1}),
        aborts=aborted,
    )

    stop_windows = after(
        trace,
        lambda row: row["edge"] in stop_edges
                    and row.get("inputs", {}).get("ena") == 1,
        until=TO_END,
        aborts=lambda row: reset(row) or sync_reset(row),
    )

    verdicts = []
    for window in start_windows:
        verdicts.append(
            eventually(
                window,
                lambda row: row.get("outputs", {}).get("busy") == 1,
                strong=False,
                after_activation=True,
            )
        )

    for window in stop_windows:
        verdicts.append(
            eventually(
                window,
                lambda row: row.get("outputs", {}).get("busy") == 0,
                strong=False,
                after_activation=True,
            )
        )

    return worst(verdicts)

