            sample_count = 1

        scl_sample = outputs.get("cscl")
        sda_sample = outputs.get("csda")
        if scl_sample not in (0, 1) or sda_sample not in (0, 1):
            return (None, edge, "filter sampling occurred but synchronized sample probes were unavailable")

        for _ in range(sample_count):
            histories["sscl"].append(scl_sample)
            histories["sscl"] = histories["sscl"][-3:]
            histories["ssda"].append(sda_sample)
            histories["ssda"] = histories["ssda"][-3:]

            expected_sscl = 1 if sum(histories["sscl"]) >= 2 else 0
            expected_ssda = 1 if sum(histories["ssda"]) >= 2 else 0
            actual_sscl = outputs.get("sscl")
            actual_ssda = outputs.get("ssda")

            if actual_sscl != expected_sscl:
                return (False, edge, f"sscl was {actual_sscl}, expected majority {expected_sscl} of the three synchronized SCL samples")
            if actual_ssda != expected_ssda:
                return (False, edge, f"ssda was {actual_ssda}, expected majority {expected_ssda} of the three synchronized SDA samples")

