    return (True, None, "sscl and ssda matched majority logic over their respective three-sample histories")

def decide(trace):
    def value(row, name):
        return row['outputs'].get(name, row['inputs'].get(name))

    cases = (
        ('scl_i', 'fscl', 'sscl'),
        ('sda_i', 'fsda', 'ssda'),
    )
    findings = []

    for raw, history, filtered in cases:
        for start in range(1, len(trace)):
            before = value(trace[start - 1], raw)
            if value(trace[start], raw) == before:
                continue

            end = None
            for candidate in range(start + 1, len(trace)):
                if value(trace[candidate], raw) == before:
                    end = candidate
                    break
            if end is None:
                continue

            # A short glitch is qualified by ending before the corresponding
            # synchronized sampling history changes.  No filter interval or
            # cycle count is invented.
            history_unchanged = all(
                value(trace[k], history) == value(trace[start - 1], history)
                for k in range(start, end + 1)
            )
            if not history_unchanged:
                continue

            baseline = value(trace[start - 1], filtered)
            bad = None
            for k in range(start, end + 1):
                if value(trace[k], filtered) != baseline:
                    bad = k
                    break

            if bad is not None:
                findings.append((
                    False,
                    trace[bad]['edge'],
                    f'{filtered} changed during a short {raw} glitch before {history} changed'
                ))
            else:
                findings.append((
                    True,
                    trace[end]['edge'],
                    f'short {raw} glitch had no corresponding {filtered} change while present'
                ))

    if not findings:
        return (None, None,
                'no completed short SCL or SDA glitch invisible to its sampling history occurred')

    for ok, edge, detail in findings:
        if not ok:
            return (False, edge, detail)
    return (True, findings[-1][1],
            f'{len(findings)} short glitch effect(s) were reduced at the filtered outputs')

