def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def value(row, name):
        return row['outputs'].get(name)

    def pair(row, first, second):
        return (value(row, first), value(row, second))

    def captured(row):
        return pair(row, 'cscl', 'csda')

    def filtered(row):
        return pair(row, 'sscl', 'ssda')

    def reset(row):
        return (row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1)

    # filter_cnt is the declared probe for an expired filter interval.
    # Count each distinct asserted state as one sampling event.
    samples = []
    previous_sample = False
    for row in trace:
        is_sample = bool(value(row, 'filter_cnt'))
        if is_sample and not previous_sample:
            samples.append((row, captured(row)))
        previous_sample = is_sample

    # Find the third filter sample in each consecutive run having the same
    # captured pair.  Short captured glitches therefore do not become
    # obligations to reproduce a value that the filter is meant to reject.
    qualifying = []
    run_pair = None
    run_count = 0
    for row, captured_pair in samples:
        if captured_pair == run_pair:
            run_count += 1
        else:
            run_pair = captured_pair
            run_count = 1
        if run_count == 3:
            qualifying.append((row, captured_pair))

    verdicts = []
    for row, expected in qualifying:
        opening_edge = row['edge']
        windows = after(
            trace,
            lambda r, opening_edge=opening_edge: r['edge'] == opening_edge,
            until=lambda r, expected=expected: captured(r) != expected,
            aborts=reset
        )
        verdicts.extend(
            eventually(
                window,
                lambda r, expected=expected: filtered(r) == expected,
                strong=False,
                after_activation=False
            )
            for window in windows
        )

    return worst(verdicts)

