def decide(trace):
    def value(row, name):
        return row.get('outputs', {}).get(name, row.get('inputs', {}).get(name))

    def idle(row):
        return value(row, 'idle') == 1

    def command(code):
        return lambda row: idle(row) and value(row, 'cmd') == code

    def left_idle(row):
        return value(row, 'idle') == 0

    def command_windows(code):
        return after(trace, command(code), until=left_idle)

    def has_level(window, expected):
        return eventually(
            window,
            lambda row: value(row, 'sda_oen') == expected,
            after_activation=True,
            strong=False,
        )

    def has_ordered_levels(window, levels):
        rows = window.rows
        pos = 0
        for row in rows[1:]:
            if value(row, 'sda_oen') == levels[pos]:
                pos += 1
                if pos == len(levels):
                    return (True, row['edge'], 'sda_oen followed the required command signature')
        if not window.closed:
            return (None, window.edge, 'command window ran out before its SDA signature was observable')
        return (False, window.edge, 'sda_oen did not follow the required command signature')

    verdicts = []

    # START=1: release SDA, then drive SDA low.
    for window in command_windows(1):
        verdicts.append(has_ordered_levels(window, [1, 0]))

    # STOP=2: drive SDA low, then release it.
    for window in command_windows(2):
        verdicts.append(has_ordered_levels(window, [0, 1]))

    # READ=8: SDA is released during the read sequence.
    for window in command_windows(8):
        verdicts.append(has_level(window, 1))

    # WRITE=4: SDA reflects din; a level may already have the required value.
    for window in command_windows(4):
        expected = value(window.rows[0], 'din')
        verdicts.append(has_level(window, expected))

    # NOP=0: no command-specific sequence is started and SDA remains released.
    nop_windows = after(trace, command(0), until=left_idle)
    for window in nop_windows:
        verdicts.append(
            throughout(
                window,
                lambda row: value(row, 'sda_oen') == 1,
                after_activation=True,
            )
