        return (
            row.get("inputs", {}).get("ena") == 1
            and out(row, "write_sequence")
            and out(row, "write_stable_high_phase")
        )

    def abort(row):
        return (
            row.get("inputs", {}).get("nReset") == 0
            or row.get("inputs", {}).get("rst") == 1
            or out(row, "al")
        )

    def is_ack(row):
        return out(row, "cmd_ack")

