        trace,
        activation,
        until=is_ack,
        aborts=abort,
    )
    scl_falls = edges(trace, "scl_oen", "fall")
    verdicts = []

    for window in windows:
        rows = list(window.rows)
        start = window.edge

        phase_rows = [
            row for row in rows
            if row.get("index", row.get("edge")) >= start
            and out(row, "write_stable_high_phase")
        ]
        for row in phase_rows:
            if not out(row, "scl_oen", 1):
                verdicts.append(
                    (False, row.get("edge"),
                     "scl_oen is not released high during the stable high phase")
                )
            elif not out(row, "sda_chk", 1):
                verdicts.append(
                    (False, row.get("edge"),
                     "SDA arbitration checking is not enabled during the stable high phase")
                )

        ack_rows = [row for row in rows if is_ack(row)]
        if not ack_rows:
            verdicts.append(
                (None, start,
                 "the WRITE completion window remains open; cmd_ack was not observed")
            )
            continue

        ack = ack_rows[0]
        ack_index = ack.get("index", ack.get("edge"))
        prior = [
            row for row in rows
            if start < row.get("index", row.get("edge")) <= ack_index
        ]

        low_rows = [
            row for row in prior
            if row.get("edge") in scl_falls and out(row, "scl_oen", 0)
        ]
        if not low_rows:
            verdicts.append(
                (False, ack.get("edge"),
                 "scl_oen did not transition from released high to pulled low before cmd_ack")
            )
            continue

        low = low_rows[0]
        low_index = low.get("index", low.get("edge"))
        idle_rows = [
            row for row in prior
            if low_index <= row.get("index", row.get("edge"))
            and out(row, "idle")
        ]
        if not idle_rows:
            verdicts.append(
                (False, ack.get("edge"),
                 "the FSM did not return to idle after pulling SCL low")
            )
            continue

        if not (out(ack, "cmd_ack") and ack.get("held") == 1):
            verdicts.append(
                (False, ack.get("edge"),
                 "cmd_ack was not high for exactly one clock at WRITE completion")
            )
        else:
            verdicts.append(
                (True, ack.get("edge"),
                 "SCL was released, arbitration checking was enabled, SCL was pulled low, the FSM returned to idle, and cmd_ack pulsed for one clock")
            )

    return worst(verdicts)

