                       strong=True, after_activation=True),
        ])

    # READ: SDA is released during the SCL-high sampling phase, then SCL is
    # driven low while SDA remains released.
    for window in windows_for('read_sequence'):
        verdicts.extend([
            eventually(window, holds(scl_oen=1, sda_oen=1),
                       strong=True, after_activation=True),
            eventually(window, holds(scl_oen=0, sda_oen=1),
                       strong=True, after_activation=True),
        ])

    # WRITE: SDA follows din during the released-SCL phase, then SCL is driven
    # low.  The active-low output-enable polarity is specified by the port notes.
    for window in windows_for('write_sequence'):
        verdicts.extend([
            eventually(
                window,
                lambda row: value(row, 'scl_oen') == 1 and
                            value(row, 'sda_oen') == value(row, 'din'),
                strong=True,
                after_activation=True,
            ),
            eventually(window, holds(scl_oen=0),
                       strong=True, after_activation=True),
        ])

    return worst(verdicts)

