def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def rising(name, extra=None):
        result = []
        previous = 0
        for i, row in enumerate(trace):
            value = 1 if out(row, name) else 0
            qualifies = extra is None or extra(row)
            if value and not previous and qualifies:
                result.append(i)
            previous = value
        return result

    def command_window(start):
        rows = []
        closed = False
        for i in range(start, len(trace)):
            rows.append(i)
            if i > start and out(trace[i], 'idle'):
                closed = True
                break
        return rows, closed

    def phase_order(rows, conditions):
        position = 0
        for condition in conditions:
            found = False
            for p in range(position, len(rows)):
                if condition(trace[rows[p]]):
                    position = p + 1
                    found = True
                    break
            if not found:
                return None
        return rows[position - 1]

    def command_check(probe, phases, label):
        verdicts = []
        for start in rising(probe):
            rows, closed = command_window(start)
            ack_rows = [i for i in rows if out(trace[i], 'cmd_ack')]
            al_rows = [i for i in rows if out(trace[i], 'al')]

            if al_rows and not ack_rows:
                verdicts.append((True, trace[al_rows[0]].get('edge'),
                                 label + ' was aborted with arbitration-loss status; no acknowledgement was produced'))
                continue

            if not ack_rows:
                if not closed:
                    verdicts.append((None, trace[start].get('edge'),
                                     label + ' started but the trace ended before completion'))
                else:
                    verdicts.append((False, trace[rows[-1]].get('edge'),
                                     label + ' completed without cmd_ack'))
                continue

            runs = []
            run_start = None
            for i in ack_rows:
                if run_start is None:
                    run_start = i
                elif i != ack_rows[ack_rows.index(i) - 1] + 1:
                    runs.append((run_start, i - 1))
                    run_start = i
            if run_start is not None:
                runs.append((run_start, ack_rows[-1]))

            bad = [i for i in ack_rows if trace[i].get('held', 1) != 1]
            if len(runs) != 1 or bad:
                edge = trace[bad[0] if bad else ack_rows[0]].get('edge')
                verdicts.append((False, edge,
                                 label + ' must produce one cmd_ack pulse high for exactly one clock'))
                continue

            phase_edge = phase_order(rows, phases)
            if phase_edge is None:
                if not closed:
                    verdicts.append((None, trace[start].get('edge'),
                                     label + ' phase sequence is incomplete at the end of the trace'))
                else:
                    verdicts.append((False, trace[rows[-1]].get('edge'),
                                     label + ' does not show the required open-drain phase sequence'))
            else:
                verdicts.append((True, trace[phase_edge].get('edge'),
                                 label + ' shows the required phase order and one-clock completion pulse'))
        return verdicts

    verdicts = []

    verdicts += command_check(
        'start_sequence',
        [lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 1,
         lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 0,
         lambda r: out(r, 'scl_oen') == 0],
        'START')

    verdicts += command_check(
        'stop_sequence',
        [lambda r: out(r, 'sda_oen') == 0,
         lambda r: out(r, 'scl_oen') == 1,
         lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 1],
        'STOP')

    def write_phases(row):
        return out(row, 'sda_oen') == (1 if inp(row, 'din') else 0)

    verdicts += command_check(
        'write_sequence',
        [write_phases,
         lambda r: out(r, 'scl_oen') == 1,
         lambda r: out(r, 'scl_oen') == 0],
        'WRITE')

    verdicts += command_check(
        'read_sequence',
        [lambda r: out(r, 'sda_oen') == 1,
         lambda r: out(r, 'scl_oen') == 1,
         lambda r: out(r, 'scl_oen') == 0],
        'READ')

    for i in rising('sta_condition'):
        found = None
        for j in range(i + 1, len(trace)):
            if out(trace[j], 'busy') == 1:
                found = j
                break
        verdicts.append((True, trace[found].get('edge'), 'busy rises after the filtered START condition') if found is not None else
                        (None, trace[i].get('edge'), 'filtered START occurred but no later busy state is present'))

    for i in rising('sto_condition'):
        found = None
        for j in range(i + 1, len(trace)):
            if out(trace[j], 'busy') == 0:
                found = j
                break
        verdicts.append((True, trace[found].get('edge'), 'busy clears after the filtered STOP condition') if found is not None else
                        (None, trace[i].get('edge'), 'filtered STOP occurred but no later cleared busy state is present'))

    for i in rising('write_stable_high_phase', lambda r: inp(r, 'din') == 1 and inp(r, 'sda_i') == 0):
        found = None
        for j in range(i + 1, len(trace)):
            if out(trace[j], 'al') == 1:
                found = j
                break
        if found is None:
            verdicts.append((None, trace[i].get('edge'), 'released-high WRITE arbitration condition was not resolved in the trace'))
        else:
            released = out(trace[found], 'scl_oen') == 1 and out(trace[found], 'sda_oen') == 1
            verdicts.append((released, trace[found].get('edge'),
                             'arbitration loss asserts al and releases both open-drain lines'))

    for i in rising('slave_wait'):
        j = i
        bad = None
        while j < len(trace) and out(trace[j], 'slave_wait'):
            if out(trace[j], 'scl_oen') != 1:
                bad = j
                break
            j += 1
        verdicts.append((False, trace[bad].get('edge'), 'SCL was not released throughout the slave clock-stretching wait') if bad is not None else
                        (True, trace[i].get('edge'), 'SCL remains released during the slave clock-stretching wait'))

    if not verdicts:
        return (None, None, 'the supported command or bus situation never occurred in this trace')
    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return verdicts[-1]

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, throughout, worst

    def out(row, name):
        return row['outputs'].get(name)

    def active_command(cmd_value, probe):
        return lambda row: (
            row['inputs'].get('ena') == 1
            and row['inputs'].get('cmd') == cmd_value
            and out(row, probe) == 1
        )

    def windows(cmd_value, probe):
        return after(
            trace,
            active_command(cmd_value, probe),
            until=TO_END,
        )

    checks = []

    for w in windows(1, 'start_sequence'):
        checks.append(eventually(
            w,
            lambda row: out(row, 'sda_oen') == 0,
            strong=True,
        ))

    for w in windows(2, 'stop_sequence'):
        checks.append(eventually(
            w,
            lambda row: out(row, 'sda_oen') == 0,
            strong=True,
        ))
        checks.append(eventually(
            w,
            lambda row: out(row, 'sda_oen') == 1,
            strong=True,
        ))

    for w in windows(4, 'write_sequence'):
        checks.append(eventually(
            w,
            lambda row, w=w: out(row, 'sda_oen') == w.value('din'),
            strong=True,
        ))

    for w in windows(8, 'read_sample_window'):
        checks.append(throughout(
            w,
            lambda row: out(row, 'sda_oen') == 1,
        ))

    return worst(checks)

def decide(trace):
    def val(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def edge_of(name, direction='rise', extra=None):
        result = []
        previous = 0
        for i, row in enumerate(trace):
            current = 1 if val(row, name) else 0
            changed = ((direction == 'rise' and current and not previous) or
                       (direction == 'fall' and not current and previous) or
                       (direction == 'change' and current != previous))
            if changed and (extra is None or extra(row)):
                result.append(i)
            previous = current
        return result

    def reset_row(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    def command_attempt(probe, label):
        starts = edge_of(probe)
        verdicts = []
        all_starts = sorted(set(
            edge_of('start_sequence') + edge_of('stop_sequence') +
            edge_of('write_sequence') + edge_of('read_sequence')))

        for start in starts:
            end = len(trace) - 1
            aborted = False
            for i in range(start, len(trace)):
                if reset_row(trace[i]):
                    aborted = True
                    end = i
                    break
                if i > start and i in all_starts:
                    end = i - 1
                    break
                if i > start and not val(trace[i], probe):
                    end = i
                    break

            if aborted:
                verdicts.append((None, trace[start].get('edge'),
                                 label + ' attempt was aborted by reset; no completion was owed'))
                continue

            ack = None
            for i in range(start, min(end + 2, len(trace))):
                if reset_row(trace[i]):
                    aborted = True
                    break
                if val(trace[i], 'cmd_ack'):
                    ack = i
                    break

            if aborted:
                verdicts.append((None, trace[start].get('edge'),
                                 label + ' attempt was aborted by reset; no completion was owed'))
            elif ack is not None:
                verdicts.append((True, trace[ack].get('edge'),
                                 label + ' completed with cmd_ack'))
            elif end < len(trace) - 1 or not val(trace[end], probe):
                verdicts.append((False, trace[end].get('edge'),
                                 label + ' sequence ended without the required command acknowledgement'))
            else:
                verdicts.append((None, trace[start].get('edge'),
                                 label + ' started but the trace ended before completion'))
        return verdicts

    verdicts = []
    verdicts += command_attempt('start_sequence', 'START')
    verdicts += command_attempt('stop_sequence', 'STOP')
    verdicts += command_attempt('write_sequence', 'WRITE')
    verdicts += command_attempt('read_sequence', 'READ')

    for i in edge_of('sta_condition'):
        found = None
        for j in range(i + 1, len(trace)):
            if reset_row(trace[j]):
                break
            if val(trace[j], 'busy') == 1:
                found = j
                break
        if found is None:
            verdicts.append((None, trace[i].get('edge'),
                             'filtered START occurred, but the trace did not show the later busy state'))
        else:
            verdicts.append((True, trace[found].get('edge'),
                             'busy is asserted after the filtered START condition'))

    for i in edge_of('sto_condition'):
        found = None
        for j in range(i + 1, len(trace)):
            if reset_row(trace[j]):
                break
            if val(trace[j], 'busy') == 0:
                found = j
                break
        if found is None:
            verdicts.append((None, trace[i].get('edge'),
                             'filtered STOP occurred, but the trace did not show the later cleared busy state'))
        else:
            verdicts.append((True, trace[found].get('edge'),
                             'busy is cleared after the filtered STOP condition'))

    for i in edge_of('write_stable_high_phase', extra=lambda r: inp(r, 'din') == 1 and val(r, 'ssda') == 0):
        found = None
        for j in range(i + 1, len(trace)):
            if reset_row(trace[j]):
                break
            if val(trace[j], 'al') == 1:
                found = j
                break
        if found is None:
            verdicts.append((None, trace[i].get('edge'),
                             'the released-high WRITE arbitration situation was not resolved in the trace'))
        else:
            verdicts.append((True, trace[found].get('edge'),
                             'arbitration loss is reported by al'))

    for i in edge_of('sto_condition', extra=lambda r: val(r, 'active_command') == 1 and not val(r, 'stop_sequence')):
        found = None
        for j in range(i + 1, len(trace)):
            if reset_row(trace[j]):
                break
            if val(trace[j], 'al') == 1:
                found = j
                break
        if found is None:
            verdicts.append((None, trace[i].get('edge'),
                             'unexpected STOP occurred during an active non-STOP command, but the trace ended before al'))
        else:
            verdicts.append((True, trace[found].get('edge'),
                             'unexpected STOP during an active command is reported by al'))

    for i in edge_of('read_sample_window'):
        for j in range(i + 1, len(trace)):
            if reset_row(trace[j]):
                break
            if not val(trace[j], 'read_sample_window'):
                break
            if j in edge_of('sscl'):
                expected = val(trace[j], 'ssda')
                captured = None
                for k in range(j, min(j + 2, len(trace))):
                    if val(trace[k], 'dout') == expected:
                        captured = k
                        break
                if captured is None:
                    verdicts.append((False, trace[j].get('edge'),
                                     'READ sampling window did not produce the synchronized filtered SDA value on dout'))
                else:
                    verdicts.append((True, trace[captured].get('edge'),
                                     'dout captures the filtered SDA value during READ'))
                break

    if not verdicts:
        return (None, None, 'the supported command or named bus situation never occurred in this trace')
    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return verdicts[-1]

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    def rising(port, i):
        return bool(out(trace[i], port)) and (i == 0 or not bool(out(trace[i - 1], port)))

    def reset(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    sequences = (
        ('start_sequence', 'START'),
        ('stop_sequence', 'STOP'),
        ('write_sequence', 'WRITE'),
        ('read_sequence', 'READ'),
    )
    starts = []
    for probe, label in sequences:
        for i, row in enumerate(trace):
            if (rising(probe, i) and inp(row, 'ena') == 1
                    and not reset(row) and not out(row, 'al')):
                starts.append((i, probe, label))
    starts.sort(key=lambda item: item[0])

    if not starts:
        return (None, None, 'no enabled supported command sequence occurred in this trace')

    verdicts = []
    for n, (start, probe, label) in enumerate(starts):
        next_start = starts[n + 1][0] if n + 1 < len(starts) else len(trace)
        ack = None
        arbitration_loss = None
        aborted = False

        for i in range(start, next_start):
            row = trace[i]
            if reset(row):
                aborted = True
                break
            if out(row, 'al') and (i == start or not out(trace[i - 1], 'al')):
                arbitration_loss = i
                break
            if out(row, 'cmd_ack') and (i == start or not out(trace[i - 1], 'cmd_ack')):
                ack = i
                break

        if aborted:
            verdicts.append((None, trace[start].get('edge'),
                             label + ' command was reset-aborted; no response was owed'))
        elif arbitration_loss is not None:
            verdicts.append((True, trace[arbitration_loss].get('edge'),
                             label + ' command reported arbitration loss through al'))
        elif ack is not None:
            verdicts.append((True, trace[ack].get('edge'),
                             label + ' command completed with cmd_ack'))
        else:
            verdicts.append((None, trace[start].get('edge'),
                             label + ' command began but the trace ended before completion or arbitration loss'))

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return verdicts[-1]

def decide(trace):
    def inp(row, name, default=None):
        return row.get('inputs', {}).get(name, default)

    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def edge_of(port, kind):
        result = set()
        previous = None
        for i, row in enumerate(trace):
            value = bool(out(row, port, 0))
            if i:
                changed = value != previous
                if ((kind == 'rise' and value and not previous)
                        or (kind == 'fall' and not value and previous)
                        or (kind == 'change' and changed)):
                    result.add(i)
            previous = value
        return result

    def reset(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    def rising_probe(port):
        return edge_of(port, 'rise')

    def first_index(start, stop, predicate):
        for i in range(start, stop):
            if predicate(trace[i]):
                return i
        return None

    def command_attempts():
        probes = (
            ('start_sequence', 'START'),
            ('stop_sequence', 'STOP'),
            ('write_sequence', 'WRITE'),
            ('read_sequence', 'READ'),
        )
        found = []
        for probe, label in probes:
            for i in sorted(rising_probe(probe)):
                row = trace[i]
                if inp(row, 'ena') == 1 and inp(row, 'cmd') in (1, 2, 4, 8):
                    found.append((i, probe, label, inp(row, 'cmd')))
        return sorted(found)

    attempts = command_attempts()
    verdicts = []

    for n, (start, probe, label, command) in enumerate(attempts):
        limit = attempts[n + 1][0] if n + 1 < len(attempts) else len(trace)
        reset_at = first_index(start, limit, reset)
        if reset_at is not None:
            verdicts.append((None, trace[start].get('edge'),
                             label + ' attempt was reset-aborted; no response was owed'))
            continue

        al_at = first_index(start + 1, limit,
                            lambda r: out(r, 'al', 0) == 1)
        ack_at = first_index(start + 1, limit,
                             lambda r: out(r, 'cmd_ack', 0) == 1)
        terminal = min((x for x in (al_at, ack_at) if x is not None),
                       default=None)

        if terminal is None:
            verdicts.append((False, trace[start].get('edge'),
                             label + ' supported command produced neither cmd_ack nor arbitration-loss termination'))
            continue

        if al_at is not None and (ack_at is None or al_at < ack_at):
            if label != 'WRITE' and command not in (1, 2):
                verdicts.append((False, trace[al_at].get('edge'),
                                 label + ' aborted with al although no permitted command arbitration case was observed'))
            else:
                verdicts.append((True, trace[al_at].get('edge'),
                                 label + ' command reported arbitration loss through al'))
            continue

        ack_row = trace[ack_at]
        if ack_row.get('held') != 1:
            verdicts.append((False, ack_row.get('edge'),
                             label + ' cmd_ack was not high for exactly one clock'))
            continue

        rows = trace[start:ack_at + 1]
        if label == 'START':
            required = (
                lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 1,
                lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 0,
                lambda r: out(r, 'scl_oen') == 0 and out(r, 'sda_oen') == 0,
            )
        elif label == 'STOP':
            required = (
                lambda r: out(r, 'sda_oen') == 0,
                lambda r: out(r, 'scl_oen') == 1,
                lambda r: out(r, 'scl_oen') == 1 and out(r, 'sda_oen') == 1,
            )
        elif label == 'WRITE':
            expected_sda = 0 if inp(trace[start], 'din') == 0 else 1
            required = (
                lambda r, v=expected_sda: out(r, 'sda_oen') == v,
                lambda r: out(r, 'scl_oen') == 1,
                lambda r: out(r, 'scl_oen') == 0,
            )
        else:
            required = (
                lambda r: out(r, 'sda_oen') == 1,
                lambda r: out(r, 'scl_oen') == 1,
                lambda r: out(r, 'scl_oen') == 0,
            )

        position = 0
        for requirement in required:
            while position < len(rows) and not requirement(rows[position]):
                position += 1
            if position == len(rows):
                verdicts.append((False, ack_row.get('edge'),
                                 label + ' command did not produce its required open-drain phase sequence'))
                break
            position += 1
        else:
            verdicts.append((True, ack_row.get('edge'),
                             label + ' command completed with the required phase sequence and one-clock cmd_ack'))

    for condition, expected, description in (
        ('sta_condition', 1, 'START'),
        ('sto_condition', 0, 'STOP'),
    ):
        for i in sorted(rising_probe(condition)):
            j = first_index(i + 1, len(trace),
                            lambda r: out(r, 'busy') == expected)
            if j is None:
                verdicts.append((False, trace[i].get('edge'),
                                 description + ' filtered bus condition did not produce the required busy status'))
            else:
                verdicts.append((True, trace[j].get('edge'),
                                 description + ' filtered bus condition produced the required busy status'))

    if not verdicts:
        return (None, None, 'no supported command sequence or filtered START/STOP condition occurred')
    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return verdicts[-1]

