    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def pair(row):
        return (out(row, 'scl_oen'), out(row, 'sda_oen'))

    def has_pattern(rows, pattern):
        pos = 0
        for row in rows:
            if pair(row) == pattern[pos]:
                pos += 1
                if pos == len(pattern):
                    return True
        return False

    def active_rows(start, probe):
        rows = []
        ended = False
        for row in trace[start:]:
            if not bool(out(row, probe)):
                ended = True
                break
            rows.append(row)
        return rows, ended

    cases = [
        ('start_sequence', 'START', [(1, 1), (1, 0), (0, 0)]),
        ('stop_sequence', 'STOP', [(0, 0), (1, 0), (1, 1)]),
        ('read_sequence', 'READ', [(1, 1), (0, 1)]),
    ]

    verdicts = []
    saw_activation = False

    for probe, name, pattern in cases:
        i = 0
        while i < len(trace):
            active = bool(out(trace[i], probe))
            previous = bool(out(trace[i - 1], probe)) if i > 0 else False
            if not active or previous:
                i += 1
                continue

            saw_activation = True
            rows, ended = active_rows(i, probe)
            aborted = any(
                out(r, 'al') == 1 or
                r.get('inputs', {}).get('nReset') == 0 or
                r.get('inputs', {}).get('rst') == 1
                for r in rows
            )
            if not aborted:
                complete = ended or any(out(r, 'cmd_ack') == 1 for r in rows)
                if has_pattern(rows, pattern):
                    verdicts.append((True, None, f'{name} bit-level scl_oen/sda_oen phase pattern observed'))
                elif complete:
                    verdicts.append((False, rows[-1].get('edge'), f'{name} sequence did not generate the required scl_oen/sda_oen bit-level phase pattern'))
                else:
                    verdicts.append((None, rows[-1].get('edge'), f'{name} sequence is incomplete in the trace; bit-level phase evidence is unavailable'))
            i += len(rows) if rows else 1

    i = 0
    while i < len(trace):
        active = bool(out(trace[i], 'write_sequence'))
        previous = bool(out(trace[i - 1], 'write_sequence')) if i > 0 else False
        if not active or previous:
            i += 1
            continue

        saw_activation = True
        rows, ended = active_rows(i, 'write_sequence')
        aborted = any(
            out(r, 'al') == 1 or
            r.get('inputs', {}).get('nReset') == 0 or
            r.get('inputs', {}).get('rst') == 1
            for r in rows
        )
        if not aborted:
            din = rows[0].get('inputs', {}).get('din') if rows else None
            pattern = [(din, 1), (0, din)]
            complete = ended or any(out(r, 'cmd_ack') == 1 for r in rows)
            if has_pattern(rows, pattern):
                verdicts.append((True, None, 'WRITE bit-level scl_oen/sda_oen phase pattern observed'))
