            else:
                verdicts.append((None, rows[-1].get('edge'), 'WRITE sequence is incomplete in the trace; bit-level phase evidence is unavailable'))
        i += len(rows) if rows else 1

    if not saw_activation:
        return (None, None, 'no declared START, STOP, READ, or WRITE command-sequence situation occurred')
