def decide(trace):
    reset_values = {
        'al': 0,
        'busy': 0,
        'cmd_ack': 0,
        'scl_oen': 1,
        'sda_oen': 1,
    }

    activations = []
    for i, row in enumerate(trace):
        if row.get('inputs', {}).get('rst') != 1:
            continue

        if i == 0:
            # An initial asserted reset has no observed pre-reset state.
            continue

        previous = trace[i - 1]
        previous_inputs = previous.get('inputs', {})
        previous_outputs = previous.get('outputs', {})
        previous_non_idle = previous_outputs.get('idle') == 0
        previous_non_reset = any(
            previous_outputs.get(port) != value
            for port, value in reset_values.items()
        )
        rst_asserted = previous_inputs.get('rst') != 1

        if rst_asserted and (previous_non_idle or previous_non_reset):
            activations.append(row)

    if not activations:
        return (None, None, 'no synchronous rst assertion was observed after a non-reset state')

    for row in activations:
        outputs = row.get('outputs', {})
        bad = [
            port for port, value in reset_values.items()
            if outputs.get(port) != value
        ]
        if bad:
            return (
                False,
                row.get('edge'),
                'on the synchronous rst reset edge, expected '
                'al=0, busy=0, cmd_ack=0, scl_oen=1, and sda_oen=1; '
                'incorrect ports: ' + ', '.join(bad)
            )

    return (
        True,
        activations[0].get('edge'),
        'synchronous rst reset edge produced the reset-defined bus-status, '
        'acknowledge, and released-interface values'
    )

def decide(trace):
    reset_rows = []
    previous_rst = 0
    for row in trace:
        rst = row['inputs'].get('rst', 0)
        if rst == 1 and previous_rst == 0:
            reset_rows.append(row)
        previous_rst = rst

    if not reset_rows:
        return (None, None, 'no newly asserted synchronous rst edge occurred')

    for row in reset_rows:
        if row['outputs'].get('cmd_ack') != 0:
            return (False, row['edge'], 'cmd_ack is asserted on the synchronous rst reset edge; the reset command-FSM state must not emit a completion pulse')

    return (True, reset_rows[-1]['edge'], 'cmd_ack is low on every observed synchronous rst reset edge')

def decide(trace):
    def out(row, name, default=None):
        return row.get('outputs', {}).get(name, default)

    def probe(row, name, default=False):
        return bool(row.get('outputs', {}).get(name, default))

    verdicts = []

    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        if row.get('inputs', {}).get('rst') != 1:
            continue

        # Each route is considered only when the corresponding non-reset
        # behaviour was observable immediately before the synchronous reset.
        nonidle_before = (
            probe(prev, 'active_command') or
            not probe(prev, 'idle') or
            out(prev, 'scl_oen') == 0 or
            out(prev, 'sda_oen') == 0
        )
        if nonidle_before:
            for port in ('scl_oen', 'sda_oen'):
                if out(row, port) != 1:
                    verdicts.append((
                        False,
                        row.get('edge'),
                        "%s was %r on the synchronous rst reset edge; expected 1 (released reset interface state)" %
                        (port, out(row, port))
                    ))
                else:
                    verdicts.append((
                        True,
                        row.get('edge'),
                        "%s was reset to 1 on the synchronous rst reset edge" % port
                    ))

        if probe(prev, 'active_command') or out(prev, 'cmd_ack') == 1:
            if out(row, 'cmd_ack') != 0:
                verdicts.append((
                    False,
                    row.get('edge'),
                    "cmd_ack was %r on the synchronous rst reset edge; expected 0 with no reset-generated completion pulse" %
                    out(row, 'cmd_ack')
                ))
            else:
                verdicts.append((
                    True,
                    row.get('edge'),
                    "cmd_ack was reset to 0 on the synchronous rst reset edge"
                ))

        if out(prev, 'busy') == 1:
            if out(row, 'busy') != 0:
                verdicts.append((
                    False,
                    row.get('edge'),
                    "busy was %r on the synchronous rst reset edge; expected 0" %
                    out(row, 'busy')
                ))
            else:
                verdicts.append((
                    True,
                    row.get('edge'),
                    "busy was reset to 0 on the synchronous rst reset edge"
                ))

        if out(prev, 'al') == 1:
            if out(row, 'al') != 0:
                verdicts.append((
                    False,
                    row.get('edge'),
                    "al was %r on the synchronous rst reset edge; expected 0" %
                    out(row, 'al')
                ))
            else:
                verdicts.append((
                    True,
                    row.get('edge'),
                    "al was reset to 0 on the synchronous rst reset edge"
                ))

    if not verdicts:
        return (None, None, 'the synchronous rst reset situation was not observed after a non-reset state')

    for ok, edge, detail in verdicts:
        if not ok:
            return (False, edge, detail)
    return (True, verdicts[-1][1], 'all observed synchronous rst reset effects matched the specified reset values')

def decide(trace):
    reset_values = {
        'al': 0,
        'busy': 0,
        'cmd_ack': 0,
