def decide(trace):
    reset_edges = []
    for i in range(1, len(trace)):
        previous = trace[i - 1]['inputs'].get('nReset')
        current = trace[i]['inputs'].get('nReset')
        if previous == 1 and current == 0:
            reset_edges.append(i)

    if not reset_edges:
        return (None, None, 'nReset was never asserted low in this trace')

    expected = {
        'cmd_ack': 0,
        'busy': 0,
        'al': 0,
        'dout': 0,
        'scl_oen': 1,
        'sda_oen': 1,
    }

    for i in reset_edges:
        row = trace[i]
        bad = [
            '%s=%r, expected %r' % (port, row['outputs'].get(port), value)
            for port, value in expected.items()
            if row['outputs'].get(port) != value
        ]
        if bad:
            return (False, row['edge'],
                    'after nReset asserted low, reset state was not initialized asynchronously: '
                    + '; '.join(bad))

    return (True, trace[reset_edges[0]]['edge'],
            'nReset assertion asynchronously initialized the declared resettable outputs '
            'without requiring a clock transition')

def decide(trace):
    from specflow.refmodel.temporal import edges, worst

    falling = edges(trace, 'nReset', 'fall')
    verdicts = []
    for row in trace:
        if row['edge'] not in falling or row['inputs'].get('nReset') != 0:
            continue

        outputs = row['outputs']
        expected = {
            'cmd_ack': 0,
            'busy': 0,
            'al': 0,
            'dout': 0,
            'scl_oen': 1,
            'sda_oen': 1,
        }
        bad = [
            port for port, value in expected.items()
            if outputs.get(port) != value
        ]
        if bad:
            verdicts.append((
                False,
                row['edge'],
                'after nReset is asserted low, resettable outputs '
                f'{bad} are not in their asynchronously initialized reset states'
            ))
        else:
            verdicts.append((
                True,
                row['edge'],
                'resettable outputs are initialized when nReset is asserted low, '
                'without requiring a clk edge'
            ))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, throughout, worst

    ports = ('cmd_ack', 'busy', 'al', 'dout', 'scl_oen', 'sda_oen')

    windows = after(
        trace,
        lambda row: row['inputs'].get('nReset') == 0,
        until=lambda row: row['inputs'].get('nReset') != 0,
    )

    def reset_state_is_held(window):
        initial = {
            port: window.value(port)
            for port in ports
        }
        return throughout(
            window,
            lambda row: all(
                row['outputs'].get(port) == value
                for port, value in initial.items()
            ),
            after_activation=False,
        )

    return worst([reset_state_is_held(window) for window in windows])

