from specflow.refmodel.temporal import TO_END, after, stable, worst

def decide(trace):
    def active_and_disabled(row):
        return (row['inputs'].get('ena') == 0 and
                row['outputs'].get('active_command') == 1)

    def window_ends(row):
        return (row['inputs'].get('ena') != 0 or
                row['outputs'].get('active_command') != 1)

    # The route's ordinary case must also be visible; otherwise this trace
    # does not distinguish gating from a command that never advances.
    ordinary_progress = any(
        i > 0 and
        trace[i - 1]['inputs'].get('ena') != 0 and
        trace[i]['inputs'].get('ena') != 0 and
        trace[i - 1]['outputs'].get('active_command') == 1 and
        trace[i]['outputs'].get('active_command') == 1 and
        trace[i - 1]['outputs'].get('scl_oen') != trace[i]['outputs'].get('scl_oen')
        for i in range(len(trace))
    )

    windows = after(trace, active_and_disabled, until=window_ends)
    if not windows:
        return (None, None, 'no accepted active command was observed with ena low')
    if not ordinary_progress:
        return (None, None, 'the trace showed ena-low gating but no ordinary ena-high SCL-phase progress')

    return worst([
        stable(w, 'scl_oen')
        for w in windows
    ])

