from specflow.refmodel.temporal import TO_END, after, edges, stable, worst

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def active_disabled(row):
        return (inp(row, 'ena') == 0 and
                out(row, 'active_command') == 1)

    def command_done_or_aborted(row):
        return (inp(row, 'ena') != 0 or
                out(row, 'active_command') != 1)

    scl_windows = after(
        trace,
        active_disabled,
        until=command_done_or_aborted
    )

    # The route describes a stable START- or STOP-shaped transition while
    # ena is low.  Use the actual input transition as the trigger, rather than
    # the held line level, so an already-stable bus does not create a false
    # filtering window.
    sda_fall = edges(trace, 'sda_i', 'fall')
    sda_rise = edges(trace, 'sda_i', 'rise')

    def filtered_transition_window(row):
        if inp(row, 'ena') != 0 or inp(row, 'scl_i') != 1:
            return False
        if row.get('edge') in sda_fall or row.get('edge') in sda_rise:
            return True
        return False

    def transition_window_ends(row):
        return inp(row, 'ena') != 0 or inp(row, 'scl_i') != 1

    busy_windows = after(
        trace,
        filtered_transition_window,
        until=transition_window_ends
    )

    ordinary_progress = any(
        i > 0 and
        inp(trace[i - 1], 'ena') != 0 and
        inp(trace[i], 'ena') != 0 and
        out(trace[i - 1], 'active_command') == 1 and
        out(trace[i], 'active_command') == 1 and
        out(trace[i - 1], 'scl_oen') != out(trace[i], 'scl_oen')
        for i in range(len(trace))
    )

    if not scl_windows and not busy_windows:
        return (None, None, 'no ena-low timing or START/STOP-shaped filter window was observed')

    if not ordinary_progress:
        return (None, None, 'ena-high ordinary SCL-phase progress was not observed for route comparison')

    verdicts = []
    verdicts.extend(stable(w, 'scl_oen') for w in scl_windows)
    verdicts.extend(stable(w, 'busy') for w in busy_windows)
    return worst(verdicts)

