def decide(trace):
    # `cmd_ack` is a declared output, and `filter_cnt` is a declared probe,
    # but this obligation licenses no expectation about `cmd_ack`.
    _cmd_ack = [r.get('outputs', {}).get('cmd_ack') for r in trace]
    _filter_cnt = [r.get('outputs', {}).get('filter_cnt') for r in trace]
    return (None, None, 'This requirement constrains filter_cnt derivation from clk_cnt, not cmd_ack; no cmd_ack expectation is specified')

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def operating(row):
        return (row.get('inputs', {}).get('nReset', 1) == 1
                and row.get('inputs', {}).get('rst', 0) == 0
                and row.get('inputs', {}).get('ena', 1) == 1)

    events = []
    previous_filter = 0
    for i, row in enumerate(trace):
        if not operating(row):
            previous_filter = 0
            continue
        current_filter = 1 if out(row, 'filter_cnt') else 0
        if current_filter and not previous_filter:
            events.append((i, row.get('edge'), row.get('inputs', {}).get('clk_cnt', 0)))
        previous_filter = current_filter

    if len(events) < 2:
        return (None, None,
                'fewer than two filter_cnt expirations were observed while the module was operating; the sampling interval is not decidable')

    for (start_i, start_edge, start_cnt), (end_i, end_edge, end_cnt) in zip(events, events[1:]):
        if start_cnt != end_cnt:
            continue
        expected = max(1, start_cnt // 4)
        enabled_edges = 0
        for row in trace[start_i + 1:end_i + 1]:
            if operating(row) and out(row, 'clk_en'):
                enabled_edges += row.get('held', 1)
        if enabled_edges != expected:
            return (False, end_edge,
                    f'filter_cnt sampling interval was {enabled_edges} enabled edges for clk_cnt={start_cnt}; expected floor(clk_cnt/4)={start_cnt // 4}, with a minimum interval of 1')

    checked = 0
    for (start_i, start_edge, start_cnt), (end_i, end_edge, end_cnt) in zip(events, events[1:]):
        if start_cnt == end_cnt:
            checked += 1
    if checked == 0:
        return (None, None,
                'clk_cnt changed between every observed filter_cnt expiration pair; no constant-clk_cnt interval was available to decide derivation')
    return (True, None,
            'filter_cnt expirations matched the SDA/SCL sampling interval derived from clk_cnt: floor(clk_cnt/4), minimum 1 enabled edge')

