def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset_active(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1)

    # With no authoritative cmd encoding table, recognize the named START
    # command through its declared FSM situation rather than inventing a
    # numeric value for cmd.
    trigger = None
    for i in range(1, len(trace)):
        if reset_active(trace[i]):
            continue
        if (out(trace[i - 1], 'idle') == 1 and
                out(trace[i], 'start_sequence') == 1):
            trigger = i
            break

    if trigger is None:
        return (None, None,
                'START command situation never occurred; no declared cmd encoding was assumed')

    for i in range(trigger + 1, len(trace)):
        if reset_active(trace[i]):
            return (None, trace[i]['edge'],
                    'START attempt was aborted by reset')

        if (out(trace[i - 1], 'sda_oen') == 1 and
                out(trace[i], 'sda_oen') == 0 and
                out(trace[i], 'scl_oen') == 1):
            return (True, trace[i]['edge'],
                    'START decode produced the routed sda_oen 1-to-0 transition while scl_oen remained released')

        if out(trace[i], 'idle') == 1:
            return (False, trace[i]['edge'],
                    'START command situation completed without the required sda_oen transition while scl_oen was released')

    return (None, trace[-1]['edge'],
            'START command situation occurred but the trace ended before its routed output transition was observable')

