    return (None, None, "I2C_CMD_START has no authoritative cmd encoding; sda_oen is observable only through the START effect owned by REQ-0131")

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    # No authoritative cmd encoding table is supplied.  Use the declared
    # START-sequence probe as the port-level signature of decoding START.
    starts = []
    for i, row in enumerate(trace):
        if reset_active(row):
            continue
        was_start = i > 0 and out(trace[i - 1], 'start_sequence') == 1
        if out(row, 'start_sequence') == 1 and not was_start:
            if i == 0 or out(trace[i - 1], 'idle') == 1:
                starts.append(i)

    if not starts:
        return (None, None,
                'START command situation never occurred; no numeric cmd encoding was assumed')

    for start in starts:
        for i in range(start, len(trace)):
            row = trace[i]
            if reset_active(row):
                return (None, row['edge'],
                        'START decoding attempt was aborted by reset')

            previous = trace[i - 1] if i > 0 else None
            if (previous is not None and
                    out(previous, 'sda_oen') == 1 and
                    out(row, 'sda_oen') == 0 and
                    out(row, 'scl_oen') == 1):
                return (True, row['edge'],
                        'START decoding produced the licensed sda_oen 1-to-0 transition while scl_oen remained released')

            if i > start and out(row, 'start_sequence') != 1:
                return (False, row['edge'],
                        'START sequence ended without the licensed sda_oen transition while scl_oen was released')

    return (None, trace[-1]['edge'],
            'START command situation occurred but the trace ended before its routed transition was observable')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    attempts = []
    for i, row in enumerate(trace):
        if reset_active(row) or out(row, 'start_sequence') != 1:
            continue
        previous = trace[i - 1] if i > 0 else None
        if (previous is not None and
                not reset_active(previous) and
                out(previous, 'start_sequence') != 1 and
                out(previous, 'idle') == 1):
            attempts.append(i)

    if not attempts:
        return (None, None,
                'START decoding situation never occurred; no cmd encoding was assumed')

    unknown_edge = None
    unknown_detail = None
    for start in attempts:
        found = False
        closed = False
        for i in range(start + 1, len(trace)):
            row = trace[i]
            if reset_active(row):
                if unknown_edge is None:
                    unknown_edge = row['edge']
                    unknown_detail = 'START decoding attempt was aborted by reset'
                break

            previous = trace[i - 1]
            if (out(previous, 'sda_oen') == 1 and
                    out(row, 'sda_oen') == 0 and
                    out(row, 'scl_oen') == 1):
                found = True
                break

            if out(row, 'start_sequence') != 1:
                closed = True
                break

        if found:
            continue
        if closed:
            return (False, trace[start]['edge'],
                    'START decoding produced no sda_oen 1-to-0 transition while scl_oen remained released during the initial START phase')
        if unknown_edge is None:
            unknown_edge = trace[-1]['edge']
            unknown_detail = 'START decoding situation occurred but the trace ended before its routed transition was observable'

    if unknown_edge is not None:
        return (None, unknown_edge, unknown_detail)
    return (True, None,
            'Every observed START decoding occurrence produced the licensed sda_oen 1-to-0 transition while scl_oen remained released')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    def output(row, name):
        return row.get('outputs', {}).get(name)

    reset_edges = []
    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            reset_edges.append(row['edge'])

    def reset_active(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    starts = edges(trace, 'start_sequence', 'rise')
    windows = after(
        trace,
        lambda row: row['edge'] in starts,
        until=lambda row: output(row, 'start_sequence') != 1,
        aborts=lambda row: reset_active(row)
    )

    return worst([
        eventually(
            window,
            lambda row: (
                output(row, 'sda_oen') == 0 and
                output(row, 'scl_oen') == 1
            ),
            strong=False,
            after_activation=True
        )
        for window in windows
    ])

