    verdicts.extend(
        eventually(
            window,
            lambda row: row['outputs'].get('busy') == 1,
            strong=True,
            after_activation=False,
        )
        for window in starts
    )
    verdicts.extend(
        eventually(
            window,
            lambda row: row['outputs'].get('busy') == 0,
            strong=True,
            after_activation=False,
        )
        for window in stops
    )

    result = worst(verdicts)
    if result[0] is False:
        return (result[0], result[1], result[2] + '; synchronized/filtered SCL is used for the filtered START/STOP case')
    if result[0] is True:
        return (result[0], result[1], result[2] + '; synchronized/filtered SCL is used for the filtered START/STOP case')
    return result

