def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def active(row):
        return inp(row, 'nReset') == 1 and inp(row, 'rst') == 0 and inp(row, 'ena') == 1

    checked = False
    first_edge = None

    # A raw SDA transition must not immediately affect START/STOP status
    # unless the filtered detector has reported the corresponding condition.
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        if not active(row) or not active(prev):
            continue
        raw_changed = inp(row, 'sda_i') != inp(prev, 'sda_i')
        filtered_unchanged = out(row, 'ssda') == out(prev, 'ssda')
        no_filtered_condition = not (out(row, 'sta_condition') or out(row, 'sto_condition'))
        if raw_changed and filtered_unchanged and no_filtered_condition:
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if out(row, 'busy') != out(prev, 'busy'):
                return (False, row['edge'],
                        'busy changed from raw sda_i before the SDA transition was synchronized and filtered')

    # A detected START/STOP condition is the filtered observation used by busy.
    for i, row in enumerate(trace):
        if not active(row):
            continue
        if out(row, 'sta_condition'):
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if any(out(r, 'busy') == 1 for r in trace[i:]):
                continue
            return (None, row['edge'],
                    'filtered START was detected, but the trace ended before busy evidence appeared')
        if out(row, 'sto_condition'):
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if any(out(r, 'busy') == 0 for r in trace[i:]):
                continue
            return (None, row['edge'],
                    'filtered STOP was detected, but the trace ended before busy evidence appeared')

    # Arbitration must use the filtered SDA value during the declared
    # stable-high WRITE checking situation, not the raw input.
    for i, row in enumerate(trace):
        if not active(row):
            continue
        write_high = (out(row, 'write_stable_high') == 1 or
                      out(row, 'sda_chk') == 1)
        if write_high and out(row, 'sda_oen') == 1 and out(row, 'ssda') == 0:
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if any(out(r, 'al') == 1 for r in trace[i:]):
                continue
            return (None, row['edge'],
                    'filtered SDA indicated arbitration loss, but the trace ended before al asserted')
        if write_high and out(row, 'sda_oen') == 1 and out(row, 'ssda') == 1 and inp(row, 'sda_i') == 0:
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if out(row, 'al') == 1:
                return (False, row['edge'],
                        'al asserted from raw low sda_i while synchronized and filtered SDA was high')

    # At a filtered SCL rising edge in the declared READ sampling window,
    # dout must reflect the filtered SDA value.
    for i in range(1, len(trace)):
        row = trace[i]
        prev = trace[i - 1]
        if not active(row):
            continue
        filtered_scl_rise = out(prev, 'sscl') == 0 and out(row, 'sscl') == 1
        if filtered_scl_rise and out(row, 'read_sample_window') == 1:
            checked = True
            first_edge = row['edge'] if first_edge is None else first_edge
            if out(row, 'dout') != out(row, 'ssda'):
                return (False, row['edge'],
                        'dout did not capture the synchronized and filtered SDA value at the filtered SCL rising edge')

    if not checked:
        return (None, None, 'the trace contains no applicable synchronized/filtered SDA observation')
    return (True, first_edge, 'SDA observations used by busy, al, and dout are qualified by synchronized and filtered signals')

def decide(trace):
    def val(row, name):
        return row.get('outputs', {}).get(name)

    def active(row):
        return (row.get('inputs', {}).get('nReset', 1) == 1
                and row.get('inputs', {}).get('rst', 0) == 0)

    def rose(name, i):
        if i == 0:
            return False
        return val(trace[i - 1], name) == 0 and val(trace[i], name) == 1

    failures = []
    successes = []
    evidence_edge = None

    # START/STOP detection must be based on the filtered SDA transition.
    for i, row in enumerate(trace):
        if not active(row):
            continue
        sta = rose('sta_condition', i)
        sto = rose('sto_condition', i)
        if not (sta or sto):
            continue
        evidence_edge = row.get('edge') if evidence_edge is None else evidence_edge
        wanted = 1 if sta else 0
        j = i
        next_detection = len(trace)
        while j < len(trace):
            if j > i and (rose('sta_condition', j) or rose('sto_condition', j)):
                next_detection = j
                break
            if active(trace[j]) and val(trace[j], 'busy') == wanted:
                successes.append((trace[j].get('edge'),
                                  'busy follows the filtered START/STOP detection'))
                break
            j += 1
        else:
            j = next_detection
        if j >= next_detection:
            failures.append((row.get('edge'),
                             'busy did not follow the filtered START/STOP detection'))

    # Arbitration checking must use filtered SDA, not an unsynchronized raw value.
    for i, row in enumerate(trace):
        if not active(row):
            continue
        in_check = (val(row, 'write_stable_high_phase') == 1
                    and val(row, 'sda_chk') == 1
                    and val(row, 'sda_oen') == 1)
        if not in_check:
            continue
        evidence_edge = row.get('edge') if evidence_edge is None else evidence_edge
        filtered_loss = val(row, 'ssda') == 0
        j = i
        while j < len(trace):
            r = trace[j]
            still_check = (active(r)
                           and val(r, 'write_stable_high_phase') == 1
                           and val(r, 'sda_chk') == 1
                           and val(r, 'sda_oen') == 1)
            if val(r, 'al') == 1:
                if not filtered_loss:
                    failures.append((r.get('edge'),
                                     'al asserted although filtered SDA did not indicate arbitration loss'))
                else:
                    successes.append((r.get('edge'),
                                      'al reflects the filtered SDA arbitration value'))
                break
            if filtered_loss and not still_check:
                failures.append((row.get('edge'),
                                 'al did not assert for filtered SDA arbitration loss'))
                break
            if not still_check and not filtered_loss:
                successes.append((row.get('edge'),
                                  'raw SDA is not used when filtered SDA shows no loss'))
                break
            j += 1

    # Read sampling must use filtered SDA at a filtered SCL rising edge.
    for i, row in enumerate(trace):
        if not active(row) or val(row, 'read_sample_window') != 1:
            continue
        if i == 0 or val(trace[i - 1], 'sscl') != 0 or val(row, 'sscl') != 1:
            continue
        evidence_edge = row.get('edge') if evidence_edge is None else evidence_edge
        expected = val(row, 'ssda')
        j = i
        found = False
        while j < len(trace):
            r = trace[j]
            if active(r) and val(r, 'dout') == expected:
                found = True
                successes.append((r.get('edge'),
                                  'dout captures the filtered SDA value'))
                break
            if j > i and val(r, 'read_sample_window') != 1:
                break
            j += 1
        if not found:
            failures.append((row.get('edge'),
                             'dout was not captured from filtered SDA at the filtered SCL rising edge'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if successes:
        return (True, successes[0][0], successes[0][1])
    return (None, None, 'the synchronized/filtered SDA-use situations never occurred')

def decide(trace):
    def value(row, name):
        return row.get('outputs', {}).get(name)

    def changed(row, previous, name):
        return value(row, name) != value(previous, name)

    if len(trace) < 2:
        return (None, None, 'no SDA transition or subsequent state was exercised')

    raw_changes = []
    filtered_changes = set()
    filtered_scl_rises = set()
    for i in range(1, len(trace)):
        row = trace[i]
        previous = trace[i - 1]
        if row.get('inputs', {}).get('sda_i') != previous.get('inputs', {}).get('sda_i'):
            raw_changes.append(i)
        if value(row, 'ssda') != value(previous, 'ssda'):
            filtered_changes.add(i)
        if value(previous, 'sscl') == 0 and value(row, 'sscl') == 1:
            filtered_scl_rises.add(i)

    failures = []
    exercised = 0

    # A raw SDA transition must not affect START/STOP status while SCL is
    # filtered high unless the filtered SDA transition has arrived.
    for i in raw_changes:
        row = trace[i]
        if value(row, 'sscl') != 1:
            continue
        exercised += 1
        end = next((j for j in range(i, len(trace))
                    if j in filtered_changes or value(trace[j], 'sscl') != 1),
                   len(trace))
        for j in range(i, end):
            if j > 0 and changed(trace[j], trace[j - 1], 'busy'):
                failures.append((trace[j].get('edge'),
                                 'busy changed before raw sda_i was represented by filtered ssda'))
                break

    # During the declared WRITE arbitration-check phase, raw SDA must not
    # assert arbitration loss before filtered SDA presents the value.
    for i in raw_changes:
        row = trace[i]
        if not (value(row, 'write_stable_high_phase') == 1 and
                value(row, 'sda_chk') == 1 and
                value(row, 'sda_oen') == 1):
            continue
        exercised += 1
        end = next((j for j in range(i, len(trace))
                    if j in filtered_changes or
                    not (value(trace[j], 'write_stable_high_phase') == 1 and
                         value(trace[j], 'sda_chk') == 1 and
                         value(trace[j], 'sda_oen') == 1)),
                   len(trace))
        for j in range(i, end):
            if j > 0 and changed(trace[j], trace[j - 1], 'al'):
                failures.append((trace[j].get('edge'),
                                 'al changed before raw sda_i was represented by filtered ssda'))
                break

    # During READ sampling, dout must not react to raw SDA before the next
    # filtered SCL rising edge.  That edge is the declared sampling event;
    # no exact cycle latency after it is specified.
    for i in raw_changes:
        if value(trace[i], 'read_sample_window') != 1:
            continue
        exercised += 1
        end = len(trace)
        for j in range(i, len(trace)):
            if j in filtered_scl_rises or value(trace[j], 'read_sample_window') != 1:
                end = j
                break
        for j in range(i, end):
            if j > 0 and changed(trace[j], trace[j - 1], 'dout'):
                failures.append((trace[j].get('edge'),
                                 'dout changed before the filtered SCL sampling event'))
                break

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if exercised == 0:
        return (None, None, 'no SDA-use situation was exercised')
    return (True, None, 'raw SDA transitions did not affect the declared uses before synchronization and filtering')

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def changed(i, name):
        return i > 0 and out(trace[i], name) != out(trace[i - 1], name)

    def rose(i, name):
        return i > 0 and out(trace[i - 1], name) == 0 and out(trace[i], name) == 1

    def condition(i):
        return (out(trace[i], 'write_stable_high_phase') == 1 and
                out(trace[i], 'sda_chk') == 1 and
                out(trace[i], 'sda_oen') == 1)

    failures = []
    exercised = 0
    incomplete = False

    # A filtered START/STOP detection is the only declared situation in which
    # SDA may change busy.  Check the positive consequence as well as the
    # absence of a response to an unfiltered raw transition.
    for i in range(len(trace)):
        if rose(i, 'sta_condition'):
            exercised += 1
            end = next((j for j in range(i + 1, len(trace))
                        if rose(j, 'sta_condition') or rose(j, 'sto_condition')
                        or inp(trace[j], 'nReset') == 0 or inp(trace[j], 'rst') == 1),
                       len(trace))
            matches = [j for j in range(i, end) if out(trace[j], 'busy') == 1]
            if matches:
                pass
            elif end == len(trace):
                incomplete = True
            else:
                failures.append((trace[i].get('edge'),
                                 'busy did not follow the filtered START use of sda_i'))

        if rose(i, 'sto_condition'):
            exercised += 1
            end = next((j for j in range(i + 1, len(trace))
                        if rose(j, 'sta_condition') or rose(j, 'sto_condition')
                        or inp(trace[j], 'nReset') == 0 or inp(trace[j], 'rst') == 1),
                       len(trace))
            matches = [j for j in range(i, end) if out(trace[j], 'busy') == 0]
            if matches:
                pass
            elif end == len(trace):
                incomplete = True
            else:
                failures.append((trace[i].get('edge'),
                                 'busy did not follow the filtered STOP use of sda_i'))

    # During arbitration checking, a low filtered SDA is the condition that
    # licenses arbitration loss; a raw SDA transition alone is not.
    for i in range(len(trace)):
        now = condition(i)
        was = condition(i - 1) if i else False
        if now and not was and out(trace[i], 'ssda') == 0:
            exercised += 1
            end = next((j for j in range(i + 1, len(trace))
                        if not condition(j) or inp(trace[j], 'nReset') == 0
                        or inp(trace[j], 'rst') == 1), len(trace))
            if any(out(trace[j], 'al') == 1 for j in range(i, end)):
                pass
            elif end == len(trace):
                incomplete = True
            else:
                failures.append((trace[i].get('edge'),
                                 'al did not assert for the filtered SDA arbitration condition'))

    # A filtered SCL rising edge in the READ sampling window is the declared
    # use point.  The captured value must be the filtered SDA value, not raw
    # sda_i or an earlier unsynchronized sample.
    for i in range(1, len(trace)):
        if (out(trace[i - 1], 'sscl') == 0 and out(trace[i], 'sscl') == 1 and
                out(trace[i], 'read_sample_window') == 1):
            exercised += 1
            expected = out(trace[i], 'ssda')
            if out(trace[i], 'dout') == expected:
                continue
            end = next((j for j in range(i + 1, len(trace))
                        if out(trace[j], 'read_sample_window') != 1
                        or inp(trace[j], 'nReset') == 0
                        or inp(trace[j], 'rst') == 1), len(trace))
            matches = [j for j in range(i + 1, end)
                       if out(trace[j], 'dout') == expected]
            if matches:
                continue
            if end == len(trace):
                incomplete = True
            else:
                failures.append((trace[i].get('edge'),
                                 'dout did not capture the filtered SDA value at the filtered SCL sampling edge'))

    # Raw SDA changes must not produce the named observable effects before the
    # corresponding filtered use is reached.
    for i in range(1, len(trace)):
        if inp(trace[i], 'sda_i') == inp(trace[i - 1], 'sda_i'):
            continue
        if out(trace[i], 'sscl') == 1:
            filtered_sda_change = out(trace[i], 'ssda') != out(trace[i - 1], 'ssda')
            filtered_start_stop = rose(i, 'sta_condition') or rose(i, 'sto_condition')
            if not (filtered_sda_change or filtered_start_stop):
                if changed(i, 'busy'):
                    failures.append((trace[i].get('edge'),
                                     'busy changed from raw sda_i before synchronization and filtering'))
        if condition(i) and out(trace[i], 'ssda') != 0 and changed(i, 'al'):
            failures.append((trace[i].get('edge'),
                             'al changed from raw sda_i before filtered arbitration evidence'))
        if out(trace[i], 'read_sample_window') == 1:
            filtered_scl_rise = (out(trace[i - 1], 'sscl') == 0 and
                                 out(trace[i], 'sscl') == 1)
            if not filtered_scl_rise and changed(i, 'dout'):
                failures.append((trace[i].get('edge'),
                                 'dout changed from raw sda_i before the filtered read sampling edge'))

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if exercised == 0:
        return (None, None, 'no filtered SDA-use situation was exercised')
    if incomplete:
        return (None, None, 'a filtered SDA-use situation remained open when the trace ended')
    return (True, None, 'sda_i was used only through the declared synchronized and filtered situations')

