def decide(trace):
    sequence_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    finishes = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        was_active = any(out(prev, p) == 1 for p in sequence_probes)
        is_idle = out(row, 'idle') == 1
        normal = (
            inp(row, 'ena') == 1
            and inp(row, 'rst') != 1
            and inp(row, 'nReset') != 0
            and out(row, 'al') != 1
        )
        if was_active and is_idle and normal:
            finishes.append(i)

    if not finishes:
        return (None, None, 'no normal START, STOP, READ, or WRITE command completion occurred')

    for i in finishes:
        row = trace[i]
        edge = row.get('edge')
        if out(row, 'cmd_ack') != 1:
            return (False, edge, 'cmd_ack was not asserted at the normal command completion')

        total_high_edges = 0
        j = i
        while j < len(trace) and out(trace[j], 'cmd_ack') == 1:
            total_high_edges += trace[j].get('held', 0)
            j += 1

        if total_high_edges != 1:
            return (False, edge, f'cmd_ack was high for {total_high_edges} edges; expected exactly one clock cycle')

        if j == len(trace):
            return (None, edge, 'cmd_ack was asserted for one observed edge, but the trace ended before its deassertion was observed')

    return (True, None, f'{len(finishes)} normal command completion pulse(s) were each exactly one clock cycle')

def decide(trace):
    sequence_ports = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def value(row, port):
        return row.get('outputs', {}).get(port, 0)

    completions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]

        finished = any(
            value(prev, port) == 1 and value(row, port) == 0
            for port in sequence_ports
        )
        if not finished:
            continue

        # A completion is normal only when enabled and not reset or aborted
        # by arbitration loss.
        if row.get('inputs', {}).get('ena') != 1:
            continue
        if row.get('inputs', {}).get('rst') == 1:
            continue
        if row.get('inputs', {}).get('nReset') == 0:
            continue
        if value(row, 'al') == 1:
            continue

        completions.append(i)

    if not completions:
        return (None, None, 'no normal START, STOP, READ, or WRITE command completion occurred')

    for i in completions:
        row = trace[i]
        edge = row.get('edge')
        if value(row, 'cmd_ack') != 1:
            return (False, edge, 'cmd_ack was not asserted when the command sequence finished')

        duration = 0
        j = i
        while j < len(trace) and value(trace[j], 'cmd_ack') == 1:
            duration += trace[j].get('held', 0)
            j += 1

        if duration != 1:
            return (False, edge,
                    f'cmd_ack was asserted for {duration} clock edge(s) at command completion; expected exactly one')

        if i > 0 and value(trace[i - 1], 'cmd_ack') == 1:
            return (False, edge,
                    'cmd_ack was already asserted before the command-finish state, so no one-cycle completion pulse was produced')

    return (True, trace[completions[-1]].get('edge'),
            f'cmd_ack asserted for exactly one clock cycle at {len(completions)} normal command completion(s)')

