def decide(trace):
    completions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        po = prev['outputs']
        ro = row['outputs']
        if (po.get('active_command') == 1 and
                ro.get('active_command') == 0 and
                row['inputs'].get('nReset') != 0 and
                row['inputs'].get('rst') != 1 and
                ro.get('al') != 1):
            completions.append(i)

    if not completions:
        return (None, None, 'no non-aborted START, STOP, READ, or WRITE command-finish transition was observed')

    incomplete = None
    for i in completions:
        row = trace[i]
        edge = row['edge']

        if row['outputs'].get('cmd_ack') != 1:
            return (False, edge,
                    'cmd_ack was not asserted when the command finished; it must be asserted for exactly one clk cycle')

        if i > 0 and trace[i - 1]['outputs'].get('cmd_ack') == 1:
            return (False, edge,
                    'cmd_ack was already high before the command finished; the completion acknowledge must be a one-cycle pulse')

        width = row['held']
        j = i + 1
        while j < len(trace) and trace[j]['outputs'].get('cmd_ack') == 1:
            width += trace[j]['held']
            j += 1

        if width > 1:
            return (False, edge,
                    f'cmd_ack was asserted for {width} clock edges at command completion; expected exactly one clk cycle')

        if j == len(trace):
            incomplete = (None, edge,
                          'cmd_ack was high for one observed clock edge, but the falling boundary of the one-cycle pulse was not observed')

    if incomplete is not None:
        return incomplete

    return (True, trace[completions[-1]]['edge'],
            'each observed non-aborted START, STOP, READ, or WRITE command finished with an isolated one-clk cmd_ack pulse')

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def aborted(row):
        return (row.get('inputs', {}).get('nReset') == 0 or
                row.get('inputs', {}).get('rst') == 1 or
                out(row, 'al') == 1)

    completions = []
    for i in range(1, len(trace)):
        before = out(trace[i - 1], 'active_command')
        now = out(trace[i], 'active_command')
        if before == 1 and now == 0:
            completions.append(i)

    verdicts = []
    for start in completions:
        if aborted(trace[start]):
            continue

        end = len(trace)
        for j in range(start + 1, len(trace)):
            if (out(trace[j - 1], 'active_command') == 0 and
                    out(trace[j], 'active_command') == 1):
                end = j
                break

        high_runs = []
        run_rows = []
        voided = False
        for j in range(start, end):
            row = trace[j]
            if not run_rows and aborted(row):
                voided = True
                break
            if out(row, 'cmd_ack') == 1:
                run_rows.append(row)
            elif run_rows:
                high_runs.append(run_rows)
                run_rows = []
        if run_rows:
            high_runs.append(run_rows)

        if voided:
            continue

        if not high_runs:
            verdicts.append((False, trace[start].get('edge'),
                             'cmd_ack was not asserted when the bit-level command finished'))
            continue

        if len(high_runs) != 1:
            verdicts.append((False, high_runs[0][0].get('edge'),
                             'cmd_ack was asserted in more than one pulse when the command finished'))
            continue

        pulse = high_runs[0]
        width = sum(row.get('held', 0) for row in pulse)
        if width != 1:
            verdicts.append((False, pulse[0].get('edge'),
                             f'cmd_ack was asserted for {width} clock edges, expected exactly one clk cycle'))
        else:
            verdicts.append((True, pulse[0].get('edge'),
                             'cmd_ack was asserted for exactly one clk cycle when the command finished'))

    if not verdicts:
        return (None, None, 'the command-completion activation never occurred')
    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    return verdicts[0]

