    def holds(cond):
        return lambda row: all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in cond.items()
        )

    def any_of(alternatives):
        predicates = [holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    starts = edges(trace, 'sta_condition', 'rise')
    stops = edges(trace, 'sto_condition', 'rise')
    reset = any_of([
        {'nReset': 0},
        {'rst': 1},
    ])

    busy_windows = after(
        trace,
        lambda row: row['edge'] in starts,
        until=holds({'sto_condition': 1}),
        aborts=reset,
    )
    idle_windows = after(
        trace,
        lambda row: row['edge'] in stops,
        until=TO_END,
        aborts=reset,
    )

    verdicts = []
    verdicts.extend(
        throughout(window, lambda row: row['outputs']['busy'] == 1)
        for window in busy_windows
    )
    verdicts.extend(
        throughout(window, lambda row: row['outputs']['busy'] == 0)
        for window in idle_windows
    )
    return worst(verdicts)

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def rising(name, i):
        return bool(out(trace[i], name)) and (i == 0 or not bool(out(trace[i - 1], name)))

    starts = [i for i in range(len(trace)) if rising('sta_condition', i)]
    stops = [i for i in range(len(trace)) if rising('sto_condition', i)]
    failures = []
    decided = False

    # During each bus-busy interval, busy must be high.  The interval begins
    # in the state after filtered START detection and ends before STOP.
    for start in starts:
        stop = next((j for j in stops if j > start), len(trace))
        rows = trace[start + 1:stop]
        if not rows:
            continue
        decided = True
        for row in rows:
            if out(row, 'busy') != 1:
                failures.append((row['edge'], 'busy was not high during the interval after filtered START and before filtered STOP'))
                break

    # After each filtered STOP, and until a subsequent START, the bus is idle.
    for stop in stops:
        start = next((j for j in starts if j > stop), len(trace))
        rows = trace[stop + 1:start]
        if not rows:
            continue
        decided = True
        for row in rows:
            if out(row, 'busy') != 0:
                failures.append((row['edge'], 'busy was not low during the idle interval after filtered STOP'))
                break

    if failures:
        edge, detail = failures[0]
        return (False, edge, detail)
    if not decided:
        return (None, None, 'no filtered START/STOP status interval occurred in this trace')
    return (True, None, 'busy correctly indicates high during active bus intervals and low after filtered STOP')

def decide(trace):
    active = False
    seen_status_event = False
    checked = False
    last_edge = None

    for i, row in enumerate(trace):
        outputs = row.get('outputs', {})
        previous = trace[i - 1].get('outputs', {}) if i else {}

        start = bool(outputs.get('sta_condition', 0)) and not bool(previous.get('sta_condition', 0))
        stop = bool(outputs.get('sto_condition', 0)) and not bool(previous.get('sto_condition', 0))

        if start:
            active = True
            seen_status_event = True
        if stop:
            active = False
            seen_status_event = True

        if seen_status_event:
            checked = True
            last_edge = row.get('edge')
            expected = 1 if active else 0
            actual = outputs.get('busy')
            if actual != expected:
                state = 'busy' if expected else 'idle'
                return (False, last_edge,
                        f"busy was {actual!r}, expected {expected} during the {state} interval after the filtered START/STOP status event")

    if not seen_status_event:
        return (None, None, 'no filtered START or STOP condition occurred; bus-status interval was not exercised')

    return (True, last_edge, 'busy correctly indicates high during the filtered START-to-STOP interval and low afterward')

