from specflow.refmodel.temporal import TO_END, after, eventually, worst

def decide(trace):
    def active_event(row):
        return (
            row['inputs'].get('scl_i') == 0
            and row['outputs'].get('scl_oen') == 1
            and row['outputs'].get('scl_sync') == 1
            and row['outputs'].get('active_command') == 1
        )

    def closes(row):
        return (
            row['outputs'].get('cmd_ack') == 1
            or row['outputs'].get('active_command') == 0
        )

    def reset(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    windows = after(trace, active_event, until=closes, aborts=reset)
    verdicts = []
    for w in windows:
        if not w.rows:
            verdicts.append((None, w.edge, 'no observable state after the SCL synchronization event'))
            continue
        first = w.rows[0]
        if first['outputs'].get('cmd_ack') == 1:
            verdicts.append((False, first['edge'], 'cmd_ack occurred at the external SCL-fall synchronization event; timing was not restarted first'))
        else:
            verdicts.append(eventually(
                w,
                lambda r: r['outputs'].get('cmd_ack') == 1,
                strong=False,
                after_activation=False,
            ))
    return worst(verdicts)

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    active_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    results = []
    for i, row in enumerate(trace):
        if i == 0:
            continue
        previous = trace[i - 1]

        # scl_sync is the declared signature of a filtered SCL falling event
        # while the master has released SCL.  Require its transition, not just
        # its level, so an already-high probe cannot retrigger the event.
        sync_rise = out(previous, 'scl_sync') == 0 and out(row, 'scl_sync') == 1
        active = any(out(row, probe) == 1 for probe in active_probes)
        if not sync_rise or out(row, 'scl_oen') != 1 or not active:
            continue

        edge = row.get('edge')
        if out(row, 'cmd_ack') == 1:
            results.append((False, edge,
                            'cmd_ack asserted on the synchronization event; '
                            'completion was not postponed until after the reloaded low-period timing'))
            continue

        saw_abort = False
        found_ack = False
        for later in trace[i + 1:]:
            if out(later, 'nReset') == 0 or out(later, 'rst') == 1:
                saw_abort = True
                break
            if out(later, 'cmd_ack') == 1:
                found_ack = True
                results.append((True, later.get('edge'),
                                'after the filtered SCL falling event while scl_oen was released, '
                                'cmd_ack occurred only in a later state, consistent with reloaded '
                                'low-period timing'))
                break
            if not any(out(later, probe) == 1 for probe in active_probes):
                saw_abort = True
                break

        if not found_ack and not saw_abort:
            results.append((None, edge,
                            'the synchronization event occurred, but the trace ended before '
                            'command completion could be observed'))

    if not results:
        return (None, None, 'the filtered SCL synchronization event during an active command never occurred')
