def decide(trace):
    events = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]['inputs']
        row = trace[i]
        inp = row['inputs']
        for source, probe in [('scl_i', 'cscl'), ('sda_i', 'csda')]:
            if inp.get(source) != prev.get(source):
                events.append((i, source, probe, inp.get(source)))

    if not events:
        return (None, None, 'no external SCL or SDA input transition occurred; synchronization was not exercised')

    for i, source, probe, value in events:
        for j in range(i + 1, len(trace)):
            outputs = trace[j].get('outputs', {})
            if outputs.get(probe) == value:
                break
        else:
            return (False, trace[i]['edge'],
                    f'{probe} never captured the changed {source} value {value}')

    return (True, trace[events[-1][0]]['edge'],
            'every exercised external SCL/SDA change was subsequently reflected in its declared two-stage synchronization probe')

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    scl_changes = edges(trace, "scl_i", "change")
    sda_changes = edges(trace, "sda_i", "change")
    changed = scl_changes | sda_changes

    if not changed:
        return (None, None, "scl_i and sda_i did not change; synchronization capture was not exercised")

    def captured(w):
        scl = w.value("scl_i")
        sda = w.value("sda_i")
        return lambda r: (
            r["outputs"].get("cscl") == scl and
            r["outputs"].get("csda") == sda
        )

    windows = after(
        trace,
        lambda r: r["edge"] in changed,
        until=TO_END
    )

    return worst([
        eventually(
            w,
            captured(w),
            strong=True,
            after_activation=False
        )
        for w in windows
    ])

