def decide(trace):
    seen = False
    previous_active = False

    for row in trace:
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        aborted = inputs.get('nReset') == 0 or inputs.get('rst') == 1
        active = (not aborted
                  and inputs.get('ena') == 1
                  and outputs.get('filter_cnt') == 1)

        if active and not previous_active:
            seen = True
            fscl_shifted = outputs.get('fscl') == 1
            fsda_shifted = outputs.get('fsda') == 1
            if not (fscl_shifted and fsda_shifted):
                missing = []
                if not fscl_shifted:
                    missing.append('fSCL')
                if not fsda_shifted:
                    missing.append('fSDA')
                return (False, row.get('edge'),
                        'filter sampling interval expired, but synchronized sample was not shifted into '
                        + ' and '.join(missing)
                        + ' as required by "The input filter counter shall control when synchronized SCL and SDA samples are shifted into the fSCL and fSDA sample histories."')

        previous_active = active

    if not seen:
        return (None, None, 'the filter sampling interval never expired while filtering was enabled')
    return (True, None, 'each observed filter sampling expiry shifted synchronized samples into both fSCL and fSDA')

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def applies(row):
        return (
            row['inputs'].get('ena') == 1
            and row['outputs'].get('filter_cnt') == 1
        )

    def reset_active(row):
        return (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        )

    def any_reset(row):
        return reset_active(row)

    # The activation is the enabled filter-counter expiration.  Closing on
    # the complement keeps the check scoped to that qualifying occurrence.
    windows = after(
        trace,
        applies,
        until=lambda row: not applies(row),
        aborts=any_reset,
    )

    def shifted_at_activation(window):
        def holds(row):
            return (
                row['edge'] == window.edge
                and row['outputs'].get('fscl') == 1
                and row['outputs'].get('fsda') == 1
            )

        return eventually(
            window,
            holds,
            strong=True,
            after_activation=False,
        )

    return worst([
        shifted_at_activation(window)
        for window in windows
    ])

