def decide(trace):
    histories = {"sscl": [1, 1, 1], "ssda": [1, 1, 1]}
    saw_activation = False
    previous_filter_active = False

    for row in trace:
        inputs = row.get("inputs", {})
        outputs = row.get("outputs", {})
        edge = row.get("edge")
        reset = inputs.get("nReset") == 0 or inputs.get("rst") == 1

        if reset:
            histories = {"sscl": [1, 1, 1], "ssda": [1, 1, 1]}
            previous_filter_active = False
            continue

        filter_active = (
            inputs.get("ena") == 1 and outputs.get("filter_cnt") == 1
        )
        if not filter_active:
            previous_filter_active = False
            continue

        saw_activation = True
        sample_count = row.get("held", 1)
        if not isinstance(sample_count, int) or sample_count < 1:
            sample_count = 1

        scl_sample = outputs.get("cscl")
        sda_sample = outputs.get("csda")
        if scl_sample not in (0, 1) or sda_sample not in (0, 1):
            return (None, edge, "filter sampling occurred but synchronized sample probes were unavailable")

        for _ in range(sample_count):
            histories["sscl"].append(scl_sample)
            histories["sscl"] = histories["sscl"][-3:]
            histories["ssda"].append(sda_sample)
            histories["ssda"] = histories["ssda"][-3:]

            expected_sscl = 1 if sum(histories["sscl"]) >= 2 else 0
            expected_ssda = 1 if sum(histories["ssda"]) >= 2 else 0
            actual_sscl = outputs.get("sscl")
            actual_ssda = outputs.get("ssda")

            if actual_sscl != expected_sscl:
                return (False, edge, f"sscl was {actual_sscl}, expected majority {expected_sscl} of the three synchronized SCL samples")
            if actual_ssda != expected_ssda:
                return (False, edge, f"ssda was {actual_ssda}, expected majority {expected_ssda} of the three synchronized SDA samples")

        previous_filter_active = True

    if not saw_activation:
        return (None, None, "the enabled filter sampling interval never expired")
    return (True, None, "sscl and ssda matched majority logic over their respective three-sample histories")

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def majority(history):
        return 1 if sum(history) >= 2 else 0

    scl_hist = [1, 1, 1]
    sda_hist = [1, 1, 1]
    activated = False
    previous_expiry = False

    for row in trace:
        rst_active = out(row, 'nReset', 1) == 0 or out(row, 'rst', 0) == 1
        if rst_active:
            scl_hist = [1, 1, 1]
            sda_hist = [1, 1, 1]
            previous_expiry = False
            continue

        enabled = out(row, 'ena', 0) == 1
        expiry = enabled and out(row, 'filter_cnt', 0) == 1
        update = out(row, 'fscl', 0) == 1 or out(row, 'fsda', 0) == 1
        opening = expiry and update and not previous_expiry
        previous_expiry = expiry

        if not opening:
            continue

        activated = True
        if out(row, 'fscl', 0) == 1:
            scl_hist = (scl_hist + [1 if out(row, 'cscl', 0) else 0])[-3:]
            expected = majority(scl_hist)
            actual = 1 if out(row, 'sscl', 0) else 0
            if actual != expected:
                return (False, row.get('edge'),
                        f"sscl was {actual}, expected majority {expected} of the three synchronized SCL samples")

        if out(row, 'fsda', 0) == 1:
            sda_hist = (sda_hist + [1 if out(row, 'csda', 0) else 0])[-3:]
            expected = majority(sda_hist)
            actual = 1 if out(row, 'ssda', 0) else 0
            if actual != expected:
                return (False, row.get('edge'),
                        f"ssda was {actual}, expected majority {expected} of the three synchronized SDA samples")

    if not activated:
        return (None, None, 'the enabled filter sampling activation never occurred')
    return (True, None, 'sscl and ssda matched the majority of their respective three-sample histories')

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, throughout, worst

    def value(row, name):
        return row.get('outputs', {}).get(name,
               row.get('inputs', {}).get(name))

    def active(row):
        return value(row, 'ena') == 1 and value(row, 'filter_cnt') == 1

    def aborted(row):
        return value(row, 'nReset') == 0 or value(row, 'rst') == 1

    # The specification states that filter histories initialize high.
    scl_hist = [1, 1, 1]
    sda_hist = [1, 1, 1]
    expected = {}
    was_active = False

    for row in trace:
        if aborted(row):
            scl_hist = [1, 1, 1]
            sda_hist = [1, 1, 1]
            was_active = False
            continue

        now_active = active(row)
        if now_active and not was_active:
            scl_sample = value(row, 'cscl')
            sda_sample = value(row, 'csda')
            if scl_sample in (0, 1):
                scl_hist = (scl_hist + [scl_sample])[-3:]
            if sda_sample in (0, 1):
                sda_hist = (sda_hist + [sda_sample])[-3:]

            expected[row['edge']] = (
                1 if sum(scl_hist) >= 2 else 0,
                1 if sum(sda_hist) >= 2 else 0
            )
        was_active = now_active

    windows = after(
        trace,
        active,
        until=WHILE_ACTIVE,
        aborts=aborted
    )

    def majority_holds(row):
        exp = expected.get(row['edge'])
        if exp is None:
            return False
        return value(row, 'sscl') == exp[0] and value(row, 'ssda') == exp[1]

    return worst([
        throughout(
            window,
            majority_holds,
            after_activation=False
        )
        for window in windows
    ])

