def decide(trace):
    def check_line(inp, filt):
        findings = []
        for i in range(1, len(trace)):
            before = trace[i - 1]['inputs'].get(inp)
            changed = trace[i]['inputs'].get(inp)
            if changed == before:
                continue

            # A completed return to the pre-change value identifies a
            # transient excursion without inventing a duration threshold.
            ret = None
            for j in range(i + 1, len(trace)):
                if trace[j]['inputs'].get(inp) == before:
                    ret = j
                    break
            if ret is None:
                continue

            # Stop before the next raw-input change, so a later independent
            # bus transition is not attributed to this transient.
            stop = len(trace)
            for k in range(ret + 1, len(trace)):
                if trace[k]['inputs'].get(inp) != before:
                    stop = k
                    break

            expected = trace[i - 1]['outputs'].get(filt)
            for k in range(i + 1, stop):
                observed = trace[k]['outputs'].get(filt)
                if observed != expected:
                    findings.append((False, trace[k]['edge'],
                                     f'{filt} changed during a transient {inp} excursion; '
                                     'the filtered line did not suppress the short glitch'))
                    break
            else:
                findings.append((True, trace[ret]['edge'],
                                 f'{filt} remained at its pre-glitch level during the completed '
                                 f'{inp} transient'))
        return findings

    findings = check_line('scl_i', 'sscl') + check_line('sda_i', 'ssda')
    if not findings:
        return (None, None, 'no completed transient SCL or SDA glitch occurred in this trace')
    for ok, edge, detail in findings:
