                    trace[end]['edge'],
                    f'short {raw} glitch had no corresponding {filtered} change while present'
                ))

    if not findings:
        return (None, None,
                'no completed short SCL or SDA glitch invisible to its sampling history occurred')

    for ok, edge, detail in findings:
