    if not saw_sequence:
        return (None, None, 'no supported START, STOP, READ, or WRITE sequence was observed')

    if not saw_boundary:
        return (None, None, 'a supported command sequence was observed, but no observable scl_oen phase boundary occurred')

    return (
        True,
        None,
        'every observable scl_oen phase boundary had a clk_en assertion without imposing a fixed response edge'
