def decide(trace):
    from specflow.refmodel.temporal import after, sequence, throughout, worst

    def holds(cond):
        def predicate(row):
            values = row.get('outputs', {})
            return all(values.get(port) == value for port, value in cond.items())
        return predicate

    def any_condition(conditions):
        predicates = [holds(condition) for condition in conditions]
        return lambda row: any(predicate(row) for predicate in predicates)

    opens = any_condition([
        {'start_sequence': 1},
        {'stop_sequence': 1},
        {'read_sequence': 1},
        {'write_sequence': 1},
    ])
    until_ack = holds({'cmd_ack': 1})
    aborted = any_condition([
        {'al': 1},
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        lambda row: row.get('inputs', {}).get('ena') == 1 and opens(row),
        until=until_ack,
        aborts=aborted,
    )

    verdicts = []
    follows = True

    for window in windows:
        if not window.rows:
            continue

        first = window.rows[0].get('outputs', {})
        if first.get('start_sequence') == 1:
            kind = 'START'
        elif first.get('stop_sequence') == 1:
            kind = 'STOP'
        elif first.get('read_sequence') == 1:
            kind = 'READ'
        elif first.get('write_sequence') == 1:
            kind = 'WRITE'
        else:
            continue

        din = window.value('din')

        def phase(row):
            out = row.get('outputs', {})
            scl = out.get('scl_oen')
            sda = out.get('sda_oen')
            chk = out.get('sda_chk')
            stable_write_high = out.get('write_stable_high_phase') == 1

            if kind == 'START':
                legal = (scl, sda) in ((1, 1), (1, 0), (0, 0))
                expected_chk = 0
            elif kind == 'STOP':
                legal = (scl, sda) in ((0, 0), (1, 0), (1, 1))
                expected_chk = 0
            elif kind == 'READ':
                legal = (scl, sda) in ((1, 1), (0, 1))
                expected_chk = 0
            else:
                legal = (scl, sda) in ((0, din), (1, din))
                expected_chk = 1 if stable_write_high else 0

            return legal and chk == expected_chk

        checks = [throughout(window, phase, after_activation=follows)]

        if kind == 'START':
            checks.append(sequence(
                window,
                lambda r: r.get('outputs', {}).get('scl_oen') == 1 and r.get('outputs', {}).get('sda_oen') == 0,
                lambda r: r.get('outputs', {}).get('scl_oen') == 0 and r.get('outputs', {}).get('sda_oen') == 0,
                strong=True,
                after_activation=follows,
            ))
        elif kind == 'STOP':
            checks.append(sequence(
                window,
                lambda r: r.get('outputs', {}).get('scl_oen') == 1 and r.get('outputs', {}).get('sda_oen') == 0,
                lambda r: r.get('outputs', {}).get('scl_oen') == 1 and r.get('outputs', {}).get('sda_oen') == 1,
                strong=True,
                after_activation=follows,
            ))
        elif kind == 'READ':
            checks.append(sequence(
                window,
                lambda r: r.get('outputs', {}).get('scl_oen') == 0 and r.get('outputs', {}).get('sda_oen') == 1,
                strong=True,
                after_activation=follows,
            ))
        else:
            checks.append(sequence(
                window,
                lambda r: r.get('outputs', {}).get('scl_oen') == 1 and r.get('outputs', {}).get('sda_oen') == din and r.get('outputs', {}).get('sda_chk') == 1,
                lambda r: r.get('outputs', {}).get('scl_oen') == 0 and r.get('outputs', {}).get('sda_oen') == din,
                strong=True,
                after_activation=follows,
            ))

        verdicts.append(worst(checks))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, eventually, sequence, throughout, worst

    def one(name):
        return lambda r: r['outputs'].get(name) == 1

    def ack(r):
        return r['outputs'].get('cmd_ack') == 1

    def aborted(r):
        return (r['inputs'].get('nReset') == 0 or
                r['inputs'].get('rst') == 1 or
                r['outputs'].get('al') == 1)

    def phase(scl, sda, chk):
        return lambda r: (r['outputs'].get('scl_oen') == scl and
                          r['outputs'].get('sda_oen') == sda and
                          r['outputs'].get('sda_chk') == chk)

    def check_window(w, phases, allowed):
        ordered = sequence(w, *phases, strong=True,
                           after_activation=True)
        legal = throughout(w, lambda r: any(
            p(r) for p in allowed), after_activation=True)
        return worst([ordered, legal])

    def windows_for(probe):
        return after(
            trace,
            lambda r: (r['inputs'].get('ena') == 1 and one(probe)(r)),
            until=ack,
            aborts=aborted)

    results = []

    for w in windows_for('start_sequence'):
        phases = [phase(1, 1, 0), phase(1, 0, 0), phase(0, 0, 0)]
        results.append(check_window(w, phases, phases))

    for w in windows_for('stop_sequence'):
        phases = [phase(0, 0, 0), phase(1, 0, 0), phase(1, 1, 0)]
        results.append(check_window(w, phases, phases))

    for w in windows_for('read_sequence'):
        phases = [phase(0, 1, 0), phase(1, 1, 0), phase(0, 1, 0)]
        results.append(check_window(w, phases, phases))

    for w in windows_for('write_sequence'):
        din = w.value('din')
        sda_level = 0 if din == 0 else 1
        phases = [phase(0, sda_level, 0),
                  phase(1, sda_level, 1),
                  phase(0, sda_level, 0)]
        results.append(check_window(w, phases, phases))

    return worst(results)

