            verdicts.append((False, ack_row.get('edge'),
                             'cmd_ack was already high before command completion'))
            continue

        duration = 0
        j = ack_i
        while j < len(trace) and out(trace[j], 'cmd_ack') == 1:
            duration += trace[j].get('held', 1)
            j += 1

        if j == len(trace):
            verdicts.append((None, ack_row.get('edge'),
                             'cmd_ack pulse did not end before the trace ended'))
        elif duration != 1:
            verdicts.append((False, ack_row.get('edge'),
                             f'cmd_ack was high for {duration} clock edges, expected exactly 1'))
        else:
            verdicts.append((True, ack_row.get('edge'),
                             'FSM reached idle and cmd_ack pulsed for exactly one clock cycle'))

    return worst(verdicts)

from specflow.refmodel.temporal import after, eventually, worst

def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    sequence_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    starts = set()
    for i, row in enumerate(trace):
        active = any(out(row, p) == 1 for p in sequence_probes)
        previous = (i > 0 and any(out(trace[i - 1], p) == 1
                                  for p in sequence_probes))
        if active and not previous:
            starts.add(row.get('index', i))

    if not starts:
        return (None, None, 'no bit-level command sequence was observed')

    def applies(row):
        return row.get('index') in starts

    def aborts(row):
        return (out(row, 'al') == 1
                or row.get('inputs', {}).get('nReset') == 0
                or row.get('inputs', {}).get('rst') == 1)

    windows = after(
        trace,
        applies,
        until=lambda row: out(row, 'cmd_ack') == 1,
        aborts=aborts,
    )

    verdicts = []
    for window in windows:
        completion = eventually(
            window,
            lambda row: out(row, 'cmd_ack') == 1 and out(row, 'idle') == 1,
            strong=False,
            after_activation=True,
        )
        if completion[0] is not True:
            verdicts.append(completion)
            continue

        window_edges = {r.get('edge') for r in window.rows}
        ack_indices = [i for i, row in enumerate(trace)
                       if row.get('edge') in window_edges
                       and out(row, 'cmd_ack') == 1]
        if not ack_indices:
            verdicts.append((False, window.edge,
                             'command completion did not assert cmd_ack'))
            continue

        ack_i = ack_indices[0]
        ack_row = trace[ack_i]
        if out(ack_row, 'idle') != 1:
            verdicts.append((False, ack_row.get('edge'),
                             'FSM was not idle when cmd_ack asserted'))
            continue

        if ack_i > 0 and out(trace[ack_i - 1], 'cmd_ack') == 1:
            verdicts.append((False, ack_row.get('edge'),
                             'cmd_ack was already high before command completion'))
            continue

        duration = 0
        j = ack_i
        while j < len(trace) and out(trace[j], 'cmd_ack') == 1:
            duration += trace[j].get('held', 1)
            j += 1

        if duration != 1:
            verdicts.append((False, ack_row.get('edge'),
                             f'cmd_ack was high for {duration} clock edges, expected exactly 1'))
        elif j == len(trace):
            verdicts.append((None, ack_row.get('edge'),
                             'cmd_ack pulse began, but the trace ended before its one-clock duration could be confirmed'))
        else:
            verdicts.append((True, ack_row.get('edge'),
                             'FSM returned to idle and cmd_ack pulsed for exactly one clock cycle'))

    return worst(verdicts)

