def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    # Reset is active low.  A completed reset is the deasserting transition
    # after an asserted-reset state; an initial high level alone is not enough
    # to establish that this post-reset situation occurred.
