    reset_falls = edges(trace, "nReset", "fall")
    if not reset_rises:
        return (None, None, "reset completion was not observed")

    verdicts = []
    for reset_edge in reset_rises:
        # Require an earlier asserted-reset state for this reset completion.
        if not any(fall < reset_edge for fall in reset_falls):
            continue

        for port, sample in (("scl_i", "cscl"), ("sda_i", "csda")):
            changed = edges(trace, port, "change")
            post_reset_changes = {
                e for e in changed
                if e > reset_edge
            }
            if not post_reset_changes:
                continue

            windows = after(
                trace,
                lambda r, es=post_reset_changes: r["edge"] in es,
                until=TO_END,
                aborts=lambda r: r["inputs"].get("nReset") == 0
            )
            verdicts.extend(
                eventually(
                    w,
                    lambda r, p=sample, w=w, src=port:
                        r["outputs"].get(p) == w.value(src),
                    strong=True,
                    after_activation=False
                )
                for w in windows
            )

    if not verdicts:
        return (None, None, "no post-reset bus-input change was observed")
    return worst(verdicts)

