    for input_port, sample_port in (('scl_i', 'cscl'), ('sda_i', 'csda')):
        final_value = trace[-1].get('inputs', {}).get(input_port)
        start = release_index

        for i in range(release_index + 1, len(trace)):
            value = trace[i].get('inputs', {}).get(input_port)
            if value != final_value:
                start = i + 1
                final_value = value

        if start >= len(trace):
            continue

        matched = None
        for i in range(start, len(trace)):
            row = trace[i]
            if row.get('outputs', {}).get(sample_port) == final_value:
                matched = row
