    if not checks:
        return (None, None, 'no stable post-reset bus-input level was exercised')

    for ok, edge, detail in checks:
        if ok is None:
            return (None, edge, detail)

    return (True, checks[-1][1], 'post-reset stable scl_i and sda_i levels were reflected in cscl and csda')

