def decide(trace):
    from specflow.refmodel.temporal import after, eventually, worst

    def active(row):
        return (row['inputs'].get('nReset') == 1 and
                row['inputs'].get('rst') != 1)

    def captured_pair(row):
        out = row['outputs']
        return (out.get('cscl'), out.get('csda'))

    def pair_is(row, pair):
        return active(row) and captured_pair(row) == pair

    def filtered_pair_is(row, pair):
        out = row['outputs']
        return (out.get('sscl'), out.get('ssda')) == pair

    pairs = []
    for row in trace:
        if not active(row):
            continue
        pair = captured_pair(row)
        if pair not in pairs:
            pairs.append(pair)

    verdicts = []
    for pair in pairs:
        windows = after(
            trace,
            lambda row, pair=pair: pair_is(row, pair),
            until=lambda row, pair=pair: (
                not active(row) or captured_pair(row) != pair
            ),
            aborts=lambda row: (
                row['inputs'].get('nReset') == 0 or
                row['inputs'].get('rst') == 1
            )
        )
        verdicts.extend([
            eventually(
                window,
                lambda row, pair=pair: filtered_pair_is(row, pair),
                strong=True,
                after_activation=False
            )
            for window in windows
        ])

    result = worst(verdicts)
    if result[0] is False:
        return (False, result[1],
                'captured SCL/SDA pair was not passed to filtered sscl/ssda before the captured pair changed')
    if result[0] is True:
        return (True, result[1],
                'each observed captured SCL/SDA pair reached the corresponding filtered sscl/ssda pair')
    return result

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, worst

    def reset_active(row):
        return row['inputs'].get('nReset') == 0 or row['inputs'].get('rst') == 1

    def windows_for(port):
        changed = edges(trace, port, 'change')
        return after(
            trace,
            lambda r: not reset_active(r) and r['edge'] in changed,
            until=TO_END,
            aborts=reset_active,
        )

    verdicts = []
    for captured, filtered in (('cscl', 'sscl'), ('csda', 'ssda')):
        for w in windows_for(captured):
            first = w.rows[0]
            target = first['outputs'][captured]
            idx = first['index']

            # A three-sample digital filter must not copy a captured transition
            # immediately when the filtered value was previously opposite.
            if idx > 0:
                previous = trace[idx - 1]['outputs'].get(filtered)
                now = first['outputs'].get(filtered)
                if previous != target and now == target:
                    verdicts.append((
                        False,
                        first['edge'],
                        f'{filtered} copied the captured {captured} transition immediately; '
                        'the captured values must be passed through a digital input filtering stage'
                    ))
                    continue

            verdicts.append(eventually(
                w,
                lambda r, p=filtered, v=target: r['outputs'].get(p) == v,
                strong=True,
            ))

    return worst(verdicts)

