def decide(trace):
    from specflow.refmodel.temporal import TO_END, after

    def applies(row):
        return (row['inputs'].get('ena') == 1 and
                row['outputs'].get('filter_cnt') == 1)

    # One window per rising occurrence of filter-counter expiration.
    windows = after(trace, applies, until=TO_END, overlap=True)
    if not windows:
        return (None, None, 'filter counter expiration while ena was high never occurred')

    occurrences = []
    for w in windows:
        if not w.rows:
            continue
        row = w.rows[0]
        index = next((i for i, candidate in enumerate(trace)
                      if candidate.get('edge') == row.get('edge')), None)
        if index is not None:
            occurrences.append((index, row))

    if not occurrences:
        return (None, None, 'filter counter expiration while ena was high never occurred')

    scl_samples = []
    sda_samples = []
    checked = 0

    def majority(values):
        return 1 if sum(values) >= 2 else 0

    for index, row in occurrences:
        cscl = row['outputs'].get('cscl')
        csda = row['outputs'].get('csda')
        if cscl not in (0, 1) or csda not in (0, 1):
            return (None, row.get('edge'),
                    'synchronized sample value was unavailable at filter expiration')

        scl_samples.append(cscl)
        sda_samples.append(csda)
        if len(scl_samples) < 3:
            continue

        expected_scl = majority(scl_samples[-3:])
        expected_sda = majority(sda_samples[-3:])
        actual_scl = row['outputs'].get('sscl')
        actual_sda = row['outputs'].get('ssda')
        checked += 1

        if actual_scl != expected_scl or actual_sda != expected_sda:
            return (False, row.get('edge'),
                    f'filtered signals were sscl={actual_scl}, ssda={actual_sda}; '
                    f'expected majority values sscl={expected_scl}, ssda={expected_sda} '
                    'over the three most recent synchronized samples')

    if checked == 0:
        return (None, occurrences[-1][1].get('edge'),
                'fewer than three synchronized samples were available; the initial history is unspecified')

    return (True, occurrences[-1][1].get('edge'),
            f'{checked} filter-expiration occurrence(s) matched three-sample majority logic')

def decide(trace):
    scl_hist = [1, 1, 1]
    sda_hist = [1, 1, 1]
    checked = 0

    def majority(hist):
        return 1 if sum(hist) >= 2 else 0

    def sample_value(row, name):
        return row['outputs'].get(name, row['inputs'].get(name))

    for i, row in enumerate(trace):
        inputs = row['inputs']
        outputs = row['outputs']
        if inputs.get('ena') != 1:
            continue

        # These declared probes identify an actual filtering sample-shift
        # situation; filter_cnt may remain at its expiry value across states.
        if not (outputs.get('fscl') == 1 or outputs.get('fsda') == 1):
            continue

        cscl = sample_value(row, 'cscl')
        csda = sample_value(row, 'csda')
        if cscl not in (0, 1) or csda not in (0, 1):
            return (None, row['edge'],
                    'synchronized samples were not observable at a filtering sample event')

        new_scl_hist = scl_hist[1:] + [cscl]
        new_sda_hist = sda_hist[1:] + [csda]
        expected_scl = majority(new_scl_hist)
        expected_sda = majority(new_sda_hist)

        # The specification gives no latency or state-count bound. Search
        # forward for the required filtered values rather than naming a
        # particular later row.
        matched = False
        for candidate in trace[i:]:
            candidate_outputs = candidate['outputs']
            if (candidate_outputs.get('sscl') == expected_scl and
                    candidate_outputs.get('ssda') == expected_sda):
                matched = True
                break

        checked += 1
        if not matched:
            return (False, row['edge'],
                    f'filtered SCL/SDA must equal the majority of their three-sample histories; '
                    f'expected sscl={expected_scl}, ssda={expected_sda} after the sample shift')

        scl_hist = new_scl_hist
        sda_hist = new_sda_hist

    if checked == 0:
        return (None, None,
                'no filtering sample shift occurred while ena was high')
    return (True, None,
            f'checked majority filtering at {checked} sample-shift occurrence(s)')

def decide(trace):
    def value(row, name):
        return row['outputs'].get(name, row['inputs'].get(name))

    def majority(history):
        return 1 if sum(history) >= 2 else 0

    # The specification initializes the filter histories high.
    scl_history = [1, 1, 1]
    sda_history = [1, 1, 1]
    scl_expectations = []
    sda_expectations = []

    for i, row in enumerate(trace):
        if value(row, 'ena') != 1:
            continue

        # fscl/fsda are declared probes identifying the actual sample shifts.
        if value(row, 'fscl') == 1:
            sample = value(row, 'cscl')
            if sample not in (0, 1):
                return (None, row['edge'],
                        'the synchronized SCL sample was not observable at a filter sample shift')
            scl_history = scl_history[1:] + [sample]
            scl_expectations.append((i, majority(scl_history)))

        if value(row, 'fsda') == 1:
            sample = value(row, 'csda')
            if sample not in (0, 1):
                return (None, row['edge'],
                        'the synchronized SDA sample was not observable at a filter sample shift')
            sda_history = sda_history[1:] + [sample]
            sda_expectations.append((i, majority(sda_history)))

    if not scl_expectations and not sda_expectations:
        return (None, None,
                'no synchronized filter sample shift occurred while filtering was enabled')

    # Each expectation is checked in the transaction opened by its sample,
    # ending at the next sample of that same signal.  This permits arbitrary
    # implementation latency without allowing a later history to satisfy an
    # earlier one.
    for signal, expectations, output_name in (
        ('SCL', scl_expectations, 'sscl'),
        ('SDA', sda_expectations, 'ssda')):
        for n, (start, expected) in enumerate(expectations):
            end = expectations[n + 1][0] if n + 1 < len(expectations) else len(trace)
            matched = False
            for j in range(start, end):
                if value(trace[j], output_name) == expected:
                    matched = True
                    break
            if not matched and n + 1 < len(expectations):
                return (False, trace[start]['edge'],
                        f'filtered {signal} must reach the majority value {expected} of its three-sample history before the next {signal} sample')

    return (True, None,
            f'checked majority computation for {len(scl_expectations)} SCL and {len(sda_expectations)} SDA sample-shift occurrence(s)')

