def decide(trace):
    if not trace:
        return (None, None, 'no operating states were observed')

    transitions = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]['outputs']
        cur = trace[i]['outputs']
        changed = (
            cur.get('sscl') != prev.get('sscl') or
            cur.get('ssda') != prev.get('ssda')
        )
        if changed:
            transitions.append(i)

    if not transitions:
        return (None, None, 'the filtered bus signals did not transition in this trace')

    for i in transitions:
        source = trace[i]['outputs']
        scl_seen = False
        sda_seen = False
        for j in range(i + 1, len(trace)):
            delayed = trace[j]['outputs']
            if delayed.get('dscl') == source.get('sscl'):
                scl_seen = True
            if delayed.get('dsda') == source.get('ssda'):
                sda_seen = True
            if scl_seen and sda_seen:
                break

        if not scl_seen or not sda_seen:
            missing = []
            if not scl_seen:
                missing.append('dSCL did not later reflect the changed filtered SCL value')
            if not sda_seen:
                missing.append('dSDA did not later reflect the changed filtered SDA value')
            return (False, trace[i]['edge'], '; '.join(missing))

    return (True, trace[transitions[-1]]['edge'], 'dSCL and dSDA later reflected every observed sscl/ssda transition')

def decide(trace):
    if len(trace) < 2:
        return (None, None, 'no filtered bus transition was observed; delayed-version maintenance is undecidable')

    sscl_changes = []
    ssda_changes = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]['outputs']
        row = trace[i]['outputs']
        if row.get('sscl') != prev.get('sscl'):
            sscl_changes.append(i)
        if row.get('ssda') != prev.get('ssda'):
            ssda_changes.append(i)

    if not sscl_changes and not ssda_changes:
        return (None, None, 'no filtered SCL or SDA transition was observed; delayed-version maintenance is undecidable')

    for i in sscl_changes:
        target = trace[i]['outputs'].get('sscl')
        if trace[i]['outputs'].get('dscl') == target:
            continue
        found = any(trace[j]['outputs'].get('dscl') == target
                    for j in range(i + 1, len(trace)))
        if not found:
            return (False, trace[i]['edge'],
                    'dSCL did not later reflect the filtered SCL value after a filtered SCL transition')

    for i in ssda_changes:
        target = trace[i]['outputs'].get('ssda')
        if trace[i]['outputs'].get('dsda') == target:
            continue
        found = any(trace[j]['outputs'].get('dsda') == target
                    for j in range(i + 1, len(trace)))
        if not found:
            return (False, trace[i]['edge'],
                    'dSDA did not later reflect the filtered SDA value after a filtered SDA transition')

    return (True, None, 'each observed filtered SCL/SDA transition was later reflected in its delayed probe')

def decide(trace):
    def operating(row):
        inp = row.get('inputs', {})
        out = row.get('outputs', {})
        return (inp.get('nReset') == 1 and
                inp.get('rst') != 1 and
                inp.get('ena') == 1 and
                out.get('al') != 1)

    checked = False
    incomplete = False

    for i in range(1, len(trace)):
        if not operating(trace[i]):
            continue
        prev = trace[i - 1].get('outputs', {})
        cur = trace[i].get('outputs', {})
        changes = []
        if cur.get('sscl') != prev.get('sscl'):
            changes.append(('sscl', 'dscl'))
        if cur.get('ssda') != prev.get('ssda'):
            changes.append(('ssda', 'dsda'))
        if not changes:
            continue

        checked = True
        for source, delayed in changes:
            expected = cur.get(source)
            seen = False
            for j in range(i, len(trace)):
                if not operating(trace[j]):
                    break
                if trace[j].get('outputs', {}).get(delayed) == expected:
                    seen = True
                    break
            if not seen:
                incomplete = True

    if not checked:
        return (None, None, 'no filtered-bus transition occurred while the module was operating')
    if incomplete:
        return (None, None, 'the trace ended before a delayed filtered-bus value could be observed')
    return (True, None, 'each observed filtered-bus change had a corresponding dSCL or dSDA value without assuming an exact delay')

