def decide(trace):
    def val(row, name):
        return row.get('outputs', {}).get(name)

    segments = []
    current = []
    for row in trace:
        reset = val(row, 'nReset') == 0 or val(row, 'rst') == 1
        enabled = row.get('inputs', {}).get('ena') == 1
        if reset:
            if current:
                segments.append(current)
                current = []
        elif enabled:
            current.append(row)
        else:
            if current:
                segments.append(current)
                current = []
    if current:
        segments.append(current)

    saw_evidence = False
    for rows in segments:
        events = []
        busy_changes = []
        for i, row in enumerate(rows):
            ssda = val(row, 'ssda')
            dsda = val(row, 'dsda')
            sscl = val(row, 'sscl')
            if sscl == 1 and ssda != dsda:
                direction = 'rise' if ssda == 0 and dsda == 1 else 'fall'
                events.append((i, direction, row.get('edge')))

            if i > 0:
                before = val(rows[i - 1], 'busy')
                after = val(row, 'busy')
                if before != after:
                    direction = 'rise' if before == 0 and after == 1 else 'fall'
                    busy_changes.append((i, direction, row.get('edge')))

        if not events and not busy_changes:
            continue
        saw_evidence = True

        if busy_changes and not events:
            return (False, busy_changes[0][2],
                    'busy changed although current filtered SDA did not differ from delayed SDA while filtered SCL was high')

        change_pos = 0
        for event_pos, event_direction, event_edge in events:
            while (change_pos < len(busy_changes)
                   and busy_changes[change_pos][0] < event_pos):
                return (False, busy_changes[change_pos][2],
                        'busy changed before a corresponding filtered SDA bus event')
            if change_pos >= len(busy_changes):
                return (False, event_edge,
                        'filtered SDA differed from delayed SDA while filtered SCL was high, but busy did not make the required transition')
            change_i, actual_direction, change_edge = busy_changes[change_pos]
            if actual_direction != event_direction:
                return (False, change_edge,
                        f'filtered SDA event required busy to {event_direction}, but busy {actual_direction}')
            change_pos += 1

        if change_pos < len(busy_changes):
            return (False, busy_changes[change_pos][2],
                    'busy changed without a corresponding filtered SDA transition while filtered SCL was high')

    if not saw_evidence:
        return (None, None, 'no enabled, non-reset filtered bus event or busy change occurred in this trace')
    return (True, None, 'filtered SDA transitions were matched by the corresponding busy rises or falls')

def decide(trace):
    events = []
    failures = []
    seen = set()

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})

        if inputs.get('ena') != 1:
            continue
        if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
            continue

        ssda = outputs.get('ssda')
        dsda = outputs.get('dsda')
        sscl = outputs.get('sscl')
        if ssda == dsda or sscl != 1:
            continue

        if ssda == 0 and dsda == 1:
            kind = 'START'
            expected_busy = 1
        elif ssda == 1 and dsda == 0:
            kind = 'STOP'
            expected_busy = 0
        else:
            continue

        seen.add(kind)
        if i == 0:
            continue

        previous_busy = trace[i - 1].get('outputs', {}).get('busy')
        current_busy = outputs.get('busy')
        events.append((kind, row.get('edge')))

        if previous_busy == current_busy or current_busy != expected_busy:
            failures.append(
                (row.get('edge'), kind, previous_busy, current_busy, expected_busy)
            )

    if not events:
        return (None, None, 'no enabled, non-reset filtered START/STOP comparison occurred')

    if failures:
        edge, kind, before, after, expected = failures[0]
        return (
            False,
            edge,
            f'{kind} comparison did not produce the required busy transition: '
            f'busy was {before} before and {after} after, expected {expected}'
        )

    if seen != {'START', 'STOP'}:
        return (
            None,
            events[-1][1],
            'only one of the required filtered START/STOP observation cases '
            f'was exercised ({sorted(seen)}); the route specifies both busy-rise '
            'and busy-fall behaviour'
        )

    return (
        True,
        None,
        'filtered SDA differences from delayed SDA while filtered SCL was high '
        'produced the required busy rise for START and busy fall for STOP'
    )

