from specflow.refmodel.temporal import edges

def decide(trace):
    ssda_falls = edges(trace, "ssda", "fall")
    seen = []
    for row in trace:
        if row["edge"] not in ssda_falls:
            continue
        inputs = row["inputs"]
        outputs = row["outputs"]
        if inputs.get("nReset") == 0 or inputs.get("rst") == 1:
            continue
        if inputs.get("ena") != 1:
            continue
        if inputs.get("scl_i") != 1 or inputs.get("sda_i") != 0:
            continue
        if outputs.get("sscl") != 1:
            continue
        seen.append(row)
        if outputs.get("sta_condition") != 1:
            return (False, row["edge"], "filtered SDA fell while filtered SCL was high, but sta_condition was not asserted")
    if not seen:
        return (None, None, "no qualified filtered SDA high-to-low transition occurred")
    return (True, seen[0]["edge"], "sta_condition was asserted for every qualified START transition")

from specflow.refmodel.temporal import after, eventually, edges, worst


def decide(trace):
    def qualifies(row):
        return (
            row.get("inputs", {}).get("ena") == 1
            and row.get("inputs", {}).get("scl_i") == 1
            and row.get("inputs", {}).get("sda_i") == 0
        )

    def aborts(row):
        inputs = row.get("inputs", {})
        return inputs.get("nReset") == 0 or inputs.get("rst") == 1

    ssda_falls = edges(trace, "ssda", "fall")

    def applies(row):
        outputs = row.get("outputs", {})
        return (
            qualifies(row)
            and row["edge"] in ssda_falls
            and outputs.get("sscl") == 1
        )

    windows = after(trace, applies, until=applies, aborts=aborts)
    return worst([
        eventually(
            window,
            lambda row: row.get("outputs", {}).get("sta_condition") == 1,
            strong=True,
            after_activation=False,
        )
        for window in windows
    ])

