def decide(trace):
    def value(row, name):
        return row.get('outputs', {}).get(name)

    def rising_probe(index, name):
        now = value(trace[index], name) == 1
        if not now:
            return False
        if index == 0:
            return True
        return value(trace[index - 1], name) != 1

    starts = [i for i in range(len(trace)) if rising_probe(i, 'sta_condition')]
    stops = [i for i in range(len(trace)) if rising_probe(i, 'sto_condition')]

    if not starts and not stops:
        return (None, None, 'no filtered START or STOP condition occurred')

    saw_decidable = False

    for start in starts:
        following_stops = [i for i in stops if i > start]
        stop = following_stops[0] if following_stops else None
        end = stop if stop is not None else len(trace)
        rows_after_start = range(start + 1, end)

        for i in rows_after_start:
            saw_decidable = True
            if value(trace[i], 'busy') != 1:
                return (False, trace[i]['edge'],
                        'busy was not high after START detection and before STOP detection')

        if stop is None:
            if len(trace) > start + 1:
                return (None, trace[-1]['edge'],
                        'START occurred and busy remained high, but no STOP closed the transaction')
            return (None, trace[start]['edge'],
                    'START occurred without a later state showing the required busy-high value')

    for stop in stops:
        rows_after_stop = range(stop + 1, len(trace))
        for i in rows_after_stop:
            saw_decidable = True
            if value(trace[i], 'busy') == 0:
                return (True, trace[i]['edge'],
                        'busy is high after START and low after STOP')
        return (None, trace[stop]['edge'],
                'STOP occurred, but the trace ended before busy became observably low')

    if saw_decidable:
        return (True, None, 'busy remained high after START through the observed transaction')
    return (None, None, 'the required post-condition was not observable')

