def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, throughout, worst

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    # No command number is used: the contract supplies no authoritative
    # encoding table.  active_command is the declared signature of a command
    # actually being executed.
    released_rise = edges(trace, 'scl_oen', 'rise')
    filtered_fall = edges(trace, 'sscl', 'fall')

    def applies(row):
        if not (inp(row, 'ena') == 1 and out(row, 'active_command') == 1):
            return False
        if row['edge'] in released_rise:
            return out(row, 'scl_oen') == 1 and out(row, 'sscl') == 0
        if row['edge'] in filtered_fall:
            return True
        return False

    def closes(row):
        return (out(row, 'sscl') == 1 or
                out(row, 'cmd_ack') == 1 or
                out(row, 'active_command') == 0 or
                inp(row, 'ena') != 1)

    windows = after(trace, applies, until=closes)
    if not windows:
        return (None, None, 'no enabled active-command clock-stretching or multi-master synchronization situation occurred')

    verdicts = []
    for w in windows:
        verdicts.append(
            throughout(
                w,
                lambda r: out(r, 'scl_oen') == 1,
                after_activation=True))

    result = worst(verdicts)
    if result[0] is False:
        return (False, result[1], 'scl_oen was not held released while filtered SCL was low or had just fallen during an active enabled command')
    return result

def decide(trace):
    from specflow.refmodel.temporal import after, never, worst

    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def active_released(row):
        return (row.get('inputs', {}).get('ena') == 1 and
                out(row, 'active_command') == 1 and
                out(row, 'scl_oen') == 1)

    def stretching(row):
        return active_released(row) and out(row, 'slave_wait') == 1

    def synchronizing(row):
        return active_released(row) and out(row, 'scl_sync') == 1

    def until_ack(row):
        return out(row, 'cmd_ack') == 1

    stretch_windows = after(trace, stretching, until=until_ack)
    sync_windows = after(trace, synchronizing, until=until_ack)
    windows = stretch_windows + sync_windows

    if not windows:
        return (None, None, 'neither clock stretching nor multi-master clock synchronization occurred')

    verdicts = []
    for window in windows:
        verdicts.append(never(
            window,
            lambda row: out(row, 'scl_oen') == 0 and out(row, 'sscl') == 0,
            after_activation=True))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, throughout, worst

    def value(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    supported = {1, 2, 8, 4}
    stretch_rises = edges(trace, 'slave_wait', 'rise')
    sync_rises = edges(trace, 'scl_sync', 'rise')

    def applies(row, rise_edges):
        return (
            row.get('edge') in rise_edges and
            row.get('inputs', {}).get('ena') == 1 and
            row.get('inputs', {}).get('cmd') in supported and
            value(row, 'active_command') == 1 and
            value(row, 'scl_oen') == 1
        )

    windows = after(
        trace,
        lambda row: applies(row, stretch_rises) or applies(row, sync_rises),
        until=lambda row: value(row, 'cmd_ack') == 1
    )

    def released_until_filtered_high(row):
        return value(row, 'scl_oen') == 1

    def resumed_low_phase(row):
        return value(row, 'scl_oen') == 0 and value(row, 'sscl') == 1

    verdicts = []
    for window in windows:
        verdicts.append(
            throughout(
                window,
                released_until_filtered_high,
                after_activation=True
            )
        )
        verdicts.append(
            eventually(
                window,
                resumed_low_phase,
                strong=True,
                after_activation=True
            )
        )

    return worst(verdicts)

def decide(trace):
    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    saw_situation = False
    for row in trace:
        # The active-command probe identifies the design-owned transaction;
        # ena is only a stimulus qualification, not an asserted effect.
        applies = (
            row.get('inputs', {}).get('ena') == 1 and
            out(row, 'active_command') == 1 and
            (out(row, 'slave_wait') == 1 or out(row, 'scl_sync') == 1)
        )
        if not applies:
            continue

        saw_situation = True
        if out(row, 'scl_oen') != 1:
            return (
                False,
                row.get('edge'),
                'scl_oen was not released while clock stretching or '
                'multi-master clock synchronization was active; the specified '
                'postponement of driving SCL low was violated'
            )

    if not saw_situation:
        return (None, None, 'no enabled active-command clock-stretching or multi-master synchronization situation occurred')

    return (True, None, 'scl_oen remained released throughout every observed clock-stretching or multi-master synchronization state')

