from specflow.refmodel.temporal import WHILE_ACTIVE, after, stable, worst


def decide(trace):
    def holds(row, conditions):
        return all(
            row['outputs'].get(port, row['inputs'].get(port)) == value
            for port, value in conditions.items()
        )

    waits = after(
        trace,
        lambda row: holds(row, {'slave_wait': 1}) and row['inputs'].get('ena') == 1,
        until=WHILE_ACTIVE,
        aborts=lambda row: (
            row['inputs'].get('nReset') == 0
            or row['inputs'].get('rst') == 1
        ),
    )

    return worst([
        stable(window, 'scl_oen')
        for window in waits
    ] + [
        stable(window, 'sda_oen')
        for window in waits
    ])

def decide(trace):
    from specflow.refmodel.temporal import WHILE_ACTIVE, after, edges, stable, worst

    def _holds(cond):
        def predicate(row):
            return all(
                row['outputs'].get(port, row['inputs'].get(port)) == value
                for port, value in cond.items()
            )
        return predicate

    def _any(alternatives):
        predicates = [_holds(condition) for condition in alternatives]
        return lambda row: any(predicate(row) for predicate in predicates)

    applies = lambda row: (
        row['outputs'].get('slave_wait') == 1
        and row['inputs'].get('ena') == 1
    )
    aborts = _any([
        {'nReset': 0},
        {'rst': 1},
    ])

    windows = after(
        trace,
        applies,
        until=WHILE_ACTIVE,
        aborts=aborts,
    )
    if not windows:
        return (None, None, 'slave_wait never became active')

    # Through REQ-0078, stability is meaningful only when this trace also
    # demonstrates ordinary command-phase advancement outside slave_wait.
    changing = {
        port: edges(trace, port, 'change')
        for port in ('scl_oen', 'sda_oen')
    }
    ordinary_change = any(
        row['outputs'].get('active_command') == 1
        and row['outputs'].get('slave_wait') != 1
        and row['edge'] in changing[port]
        for row in trace
        for port in ('scl_oen', 'sda_oen')
    )
    if not ordinary_change:
        return (
            None,
            windows[0].edge,
            'slave_wait occurred, but the trace shows no ordinary active-command output-enable advance outside the wait; routed evidence is incomplete'
        )

    verdicts = [
        worst([
            stable(window, 'scl_oen'),
            stable(window, 'sda_oen'),
        ])
        for window in windows
    ]
    return worst(verdicts)

