def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    def rises(name):
        result = set()
        previous = None
        for row in trace:
            value = out(row, name)
            if value == 1 and previous != 1:
                result.add(row['edge'])
            previous = value
        return result

    activation_edges = rises('active_command')
    windows = []
    active = False
    rows = []
    opened_at = None

    for row in trace:
        reset_or_voided = (
            inp(row, 'nReset') == 0 or
            inp(row, 'rst') == 1 or
            inp(row, 'ena') != 1 or
            out(row, 'al') == 1 or
            out(row, 'slave_wait') == 1 or
            out(row, 'scl_sync') == 1
        )

        if not active:
            if row['edge'] in activation_edges and not reset_or_voided and inp(row, 'ena') == 1:
                active = True
                rows = [row]
                opened_at = row['edge']
            continue

        if reset_or_voided:
            active = False
            rows = []
            opened_at = None
            continue

        rows.append(row)
        if out(row, 'cmd_ack') == 1 or out(row, 'active_command') != 1:
            windows.append((opened_at, rows))
            active = False
            rows = []
            opened_at = None

    if active and rows:
        windows.append((opened_at, rows))

    verdicts = []
    for opened_at, window_rows in windows:
        ack_rows = [r for r in window_rows if out(r, 'cmd_ack') == 1]
        if not ack_rows:
            verdicts.append((None, None, 'cmd_ack did not complete before the command window ended'))
            continue

        ack = ack_rows[0]
        after_activation = [r for r in window_rows if r['edge'] != opened_at and r['edge'] <= ack['edge']]
        saw_counter_expiry = False
        saw_timing_tick = False
        tick_edge = None

        for row in after_activation:
            if out(row, 'cnt_zero') == 1:
                saw_counter_expiry = True
            if saw_counter_expiry and out(row, 'clk_en') == 1:
                saw_timing_tick = True
                tick_edge = row['edge']
                break

        if not saw_timing_tick:
            verdicts.append((False, ack['edge'], 'cmd_ack occurred without a preceding counter expiry and clk_en timing tick'))
        else:
            verdicts.append((True, ack['edge'], 'cmd_ack followed counter-generated bit-level timing via cnt_zero and clk_en'))

    if not verdicts:
        return (None, None, 'the accepted-command timing activation never occurred')

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is True:
            return verdict
    return (None, None, 'the command timing window was aborted or did not complete')

