def decide(trace):
    starts = []
    for i, row in enumerate(trace):
        out = row.get('outputs', {})
        prev = trace[i - 1].get('outputs', {}) if i else {}
        if (out.get('ena', row.get('inputs', {}).get('ena')) == 1
                and out.get('active_command', 0) == 1
                and (i == 0 or prev.get('active_command', 0) != 1)):
            starts.append(i)

    if not starts:
        return (None, None, 'no enabled active bit-level command occurred')

    verdicts = []
    for start in starts:
        start_row = trace[start]
        start_inputs = start_row.get('inputs', {})
        clk_cnt = start_inputs.get('clk_cnt')
        saw_clk_en = False
        ack_row = None
        aborted = False
        ended = False

        for i in range(start, len(trace)):
            row = trace[i]
            inputs = row.get('inputs', {})
            outputs = row.get('outputs', {})

            if inputs.get('nReset') == 0 or inputs.get('rst') == 1 or inputs.get('ena') != 1:
                aborted = True
                break
            if clk_cnt is not None and inputs.get('clk_cnt') != clk_cnt:
                aborted = True
                break
            if outputs.get('al') == 1:
                aborted = True
                break

            if outputs.get('clk_en', 0) == 1:
                saw_clk_en = True
            if outputs.get('cmd_ack', 0) == 1:
                ack_row = row
                break

            if i > start and outputs.get('active_command', 0) != 1:
                ended = True
                break

        if aborted:
            verdicts.append((None, None, 'command timing window was aborted by reset, disable, arbitration loss, or clk_cnt change'))
        elif ack_row is None:
            if ended:
                verdicts.append((False, trace[start].get('edge'), 'active command completed without the routed cmd_ack timing effect'))
            else:
                verdicts.append((None, None, 'enabled command window ran out before cmd_ack was observed'))
        elif not saw_clk_en:
            verdicts.append((False, ack_row.get('edge'), 'cmd_ack occurred before any timing-enable event; the prescaled counter had not advanced'))
        else:
            verdicts.append((True, ack_row.get('edge'), 'cmd_ack occurred after a timing-enable event during the enabled command transaction'))

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is True:
            return verdict
    return (None, None, 'no non-aborted command transaction provided decisive timing evidence')

