def decide(trace):
    from specflow.refmodel.temporal import after, edges, worst

    def holds(row, cond):
        return all(row.get("outputs", {}).get(port,
                                      row.get("inputs", {}).get(port)) == value
                   for port, value in cond.items())

    def any_condition(conditions):
        return lambda row: any(holds(row, condition) for condition in conditions)

    applies = lambda row: (
        row.get("inputs", {}).get("ena") == 1
        and row.get("outputs", {}).get("active_command") == 1
    )
    until = any_condition([{"cmd_ack": 1}])
    aborts = any_condition([
        {"al": 1},
        {"nReset": 0},
        {"rst": 1},
    ])

    windows = after(trace, applies, until=until, aborts=aborts)
    changed_scl = edges(trace, "scl_oen", "change")
    changed_sda = edges(trace, "sda_oen", "change")
    verdicts = []

    for window in windows:
        changes = [
            row for row in window.rows
            if row.get("edge") in changed_scl or row.get("edge") in changed_sda
        ]
        if not changes:
            verdicts.append((None, None,
                             "no bit-timing phase change was observed in the active command window"))
            continue

        bad = [row for row in changes
               if row.get("outputs", {}).get("clk_en") != 1]
        if bad:
            row = bad[0]
            ports = []
            if row.get("edge") in changed_scl:
                ports.append("scl_oen")
            if row.get("edge") in changed_sda:
                ports.append("sda_oen")
            verdicts.append((False, row.get("edge"),
                             f"{', '.join(ports)} advanced phase while clk_en was not asserted"))
        else:
            verdicts.append((True, changes[0].get("edge"),
                             "every observed bit-timing phase change occurred with clk_en asserted"))

    return worst(verdicts)

