    from specflow.refmodel.temporal import after, eventually, throughout, edges

    def holds(row, conditions):
        for port, value in conditions.items():
            values = row.get('outputs', {})
            if port not in values:
                values = row.get('inputs', {})
            if values.get(port) != value:
                return False
        return True

    def any_holds(conditions):
        return lambda row: any(holds(row, condition) for condition in conditions)

    # No encoding table is supplied for cmd.  The declared active_command
    # probe is therefore used as the supported-command signature.
    applies = lambda row: (
        holds(row, {'active_command': 1}) and
        row.get('inputs', {}).get('ena') == 1
    )

    windows = after(
        trace,
        applies,
        until=any_holds([{'cmd_ack': 1}]),
        aborts=any_holds([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1}
        ])
    )

    changed = {
        port: edges(trace, port, 'change')
        for port in ('scl_oen', 'sda_oen')
    }

    for window in windows:
        def gated_or_unchanged(row):
            edge = row['edge']
            changed_here = any(edge in changed[port]
                               for port in changed)
            return (not changed_here or
                    row.get('outputs', {}).get('clk_en') == 1)

        timing = throughout(
            window,
            gated_or_unchanged,
            after_activation=True
        )
        if timing[0] is False:
            for row in window.rows:
                if row['edge'] <= window.edge:
                    continue
                if (any(row['edge'] in changed[port] for port in changed) and
                        row.get('outputs', {}).get('clk_en') != 1):
                    return (False, row['edge'],
                            'scl_oen or sda_oen changed without clk_en asserted')
            return timing
        if timing[0] is None:
            return timing

        progressed = eventually(
            window,
            lambda row: (
                any(row['edge'] in changed[port] for port in changed) and
                row.get('outputs', {}).get('clk_en') == 1
            ),
            strong=False,
            after_activation=True
        )
