def decide(trace):
    from specflow.refmodel.temporal import after, edges, throughout, TO_END, worst

    def out(row, name, default=0):
        return row.get('outputs', {}).get(name, default)

    def inp(row, name, default=0):
        return row.get('inputs', {}).get(name, default)

    ena_falls = edges(trace, 'ena', 'fall')

    def active_disable(row):
        return (row.get('edge') in ena_falls
                and inp(row, 'ena') == 0
                and out(row, 'active_command') == 1)

    def reset_abort(row):
        return inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    windows = after(
        trace,
        active_disable,
        until=lambda row: inp(row, 'ena') == 1,
        aborts=reset_abort,
    )

    verdicts = []
    for window in windows:
        verdict = throughout(
            window,
            lambda row: out(row, 'cmd_ack') == 0,
            after_activation=False,
        )

        if verdict[0] is False:
            verdicts.append((False, verdict[1],
                             'cmd_ack asserted while ena was low; '
                             'the disabled interval did not suppress command completion'))
            continue

        later_completion = any(
            r.get('edge', -1) > window.edge
            and inp(r, 'ena') == 1
            and out(r, 'cmd_ack') == 1
            for r in trace
        )
        if verdict[0] is True and later_completion:
            verdicts.append((True, verdict[1],
                             'cmd_ack remained low while ena was low; '
                             'a completion pulse occurred after ena was re-enabled'))
        else:
            verdicts.append((None, window.edge,
                             'cmd_ack remained low while ena was low, but no later '
                             'completion pulse was observed to establish the routed contrast'))

    return worst(verdicts)

def decide(trace):
    from specflow.refmodel.temporal import after, edges, eventually, throughout, worst

    def active(row):
        return row.get('outputs', {}).get('active_command') == 1

    def disabled(row):
        return row.get('inputs', {}).get('ena') == 0

    def reset_asserted(row):
        inputs = row.get('inputs', {})
        return inputs.get('nReset') == 0 or inputs.get('rst') == 1

    ena_falls = edges(trace, 'ena', 'fall')
    windows = after(
        trace,
        lambda row: row.get('edge') in ena_falls and disabled(row) and active(row),
        until=lambda row: (
            row.get('inputs', {}).get('ena') == 1 or
            not active(row)
        ),
        aborts=reset_asserted
    )

    if not windows:
        return (None, None,
                'ena did not fall while an active command was in progress')

    verdict = worst([
        throughout(
            window,
            lambda row: row.get('outputs', {}).get('cmd_ack') == 0,
            after_activation=False
        )
        for window in windows
    ])

    if verdict[0] is False:
        return verdict

    enabled_completion = any(
        row.get('inputs', {}).get('ena') == 1 and
        row.get('outputs', {}).get('cmd_ack') == 1
        for row in trace
    )
    if not enabled_completion:
        return (None, None,
                'disabled active-command interval had no cmd_ack pulse, but the enabled completion contrast was not exercised')

    return verdict

