def decide(trace):
    active = False
    opened_edge = None
    events = []
    saw_activation = False
    verdicts = []

    previous = None
    previous_read_window = 0

    for row in trace:
        outputs = row.get('outputs', {})
        inputs = row.get('inputs', {})
        read_window = outputs.get('read_sample_window', 0)
        sscl = outputs.get('sscl')
        ssda = outputs.get('ssda')

        aborted = (outputs.get('al') == 1 or
                   inputs.get('nReset') == 0 or
                   inputs.get('rst') == 1)

        rising_read_window = bool(read_window == 1 and
                                  previous_read_window != 1)
        if previous is None:
            rising_sscl = False
        else:
            rising_sscl = (sscl is not None and
                           previous.get('sscl') is not None and
                           sscl > previous.get('sscl'))

        if not active and rising_read_window and inputs.get('ena') == 1 and not aborted:
            active = True
            saw_activation = True
            opened_edge = row.get('edge')
            events = []

        if active:
            if aborted:
                active = False
                events = []
                opened_edge = None
            else:
                if rising_sscl and read_window == 1:
                    events.append(row)

                if outputs.get('cmd_ack') == 1:
                    if events:
                        bad = [r for r in events
                               if r.get('outputs', {}).get('dout') !=
                                  r.get('outputs', {}).get('ssda')]
                        if bad:
                            verdicts.append((False, bad[0].get('edge'),
                                             'dout did not provide the filtered SDA bit on a filtered SCL rising edge'))
                        else:
                            verdicts.append((True, events[-1].get('edge'),
                                             'dout matched filtered SDA on each filtered SCL rising edge during the READ sample window'))
                    else:
                        verdicts.append((None, opened_edge,
                                         'the READ sample window completed without a filtered SCL rising edge'))
                    active = False
                    events = []
                    opened_edge = None

        previous = {'sscl': sscl}
        previous_read_window = read_window

    if active:
        if events:
            bad = [r for r in events
                   if r.get('outputs', {}).get('dout') !=
                      r.get('outputs', {}).get('ssda')]
            if bad:
                verdicts.append((False, bad[0].get('edge'),
                                 'dout did not provide the filtered SDA bit on a filtered SCL rising edge'))
            else:
                verdicts.append((None, opened_edge,
                                 'the READ sample window was not completed in this trace'))
        else:
            verdicts.append((None, opened_edge,
                             'the READ sample window contained no filtered SCL rising edge'))

    if not saw_activation:
        return (None, None, 'the READ sample window activation never occurred')
    if not verdicts:
        return (None, None, 'the READ sample window activation produced no completed decision')

    for verdict in verdicts:
        if verdict[0] is False:
            return verdict
    for verdict in verdicts:
        if verdict[0] is None:
            return verdict
    return verdicts[-1]

