def decide(trace):
    def out(row, name):
        return row.get('outputs', {}).get(name)

    sequence_names = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    attempts = []
    i = 0
    while i < len(trace):
        row = trace[i]
        cmd = row.get('inputs', {}).get('cmd')
        if out(row, 'idle') != 1 or cmd is None:
            i += 1
            continue

        previous_same_command_idle = (
            i > 0
            and out(trace[i - 1], 'idle') == 1
            and trace[i - 1].get('inputs', {}).get('cmd') == cmd
        )
        if previous_same_command_idle:
            i += 1
            continue

        j = i + 1
        while j < len(trace):
            r = trace[j]
            if out(r, 'idle') != 1 or r.get('inputs', {}).get('cmd') != cmd:
                break
            j += 1

        if j == len(trace) or (
            out(trace[j], 'idle') == 1
            and trace[j].get('inputs', {}).get('cmd') != cmd
        ):
            attempts.append((True, row['edge'], 'cmd remained in idle; no command sequence was entered'))
            i = j
            continue

        entered = [name for name in sequence_names if out(trace[j], name) == 1]
        if len(entered) != 1 or out(trace[j], 'idle') == 1:
            attempts.append((False, trace[j]['edge'], 'FSM left idle without entering exactly one declared command sequence'))
        else:
            attempts.append((True, trace[j]['edge'], 'FSM left idle and entered one command sequence'))
        i = j

    if not attempts:
        return (None, None, 'the idle-command activation never occurred')

    for ok, edge, detail in attempts:
        if not ok:
            return (False, edge, detail)
    return (True, None, 'each observed idle command either remained idle or entered exactly one command sequence')

def decide(trace):
    declared = {
        'idle',
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    }
    observed = any(
        declared.intersection(row.get('outputs', {}).keys())
        for row in trace
    )
    if not observed:
        return (None, None, 'declared command-FSM probes are absent from this trace')
    return (None, None, 'cannot decide command recognition: no authoritative cmd encoding table maps symbols to numeric values')

