def decide(trace):
    activations = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})
        if prev_out.get('read_sequence') == 1 and out.get('read_sequence') == 0:
            if row.get('inputs', {}).get('nReset') == 0 or row.get('inputs', {}).get('rst') == 1:
                continue
            activations.append((i, row))

    if not activations:
        return (None, None, 'the READ bit-cycle completion activation never occurred')

    for i, row in activations:
        prev = trace[i - 1]
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})
        edge = row.get('edge')
        if out.get('idle') != 1:
            return (False, edge, 'after the read bit cycle completes, the FSM did not return to idle')
        if out.get('cmd_ack') != 1:
            return (False, edge, 'after the read bit cycle completes, cmd_ack did not assert')
        if prev_out.get('cmd_ack') == 1:
            return (False, edge, 'cmd_ack was already asserted; it did not assert at READ completion')

    return (True, activations[-1][1].get('edge'), 'each completed READ bit cycle returned the FSM to idle and asserted cmd_ack')

def decide(trace):
    active = False
    aborted = False
    completions = []

    for i, row in enumerate(trace):
        inputs = row.get('inputs', {})
        outputs = row.get('outputs', {})
        reset = inputs.get('nReset') == 0 or inputs.get('rst') == 1
        read_active = outputs.get('read_sequence') == 1
        lost = outputs.get('al') == 1

        if reset:
            active = False
            aborted = False
            continue

        if read_active and not active:
            active = True
            aborted = False

        if active and lost:
            aborted = True

        if active and i > 0:
            previous = trace[i - 1].get('outputs', {})
            fell = previous.get('read_sequence') == 1 and not read_active
            if fell:
                if not aborted and outputs.get('idle') == 1:
                    completions.append(row)
                active = False
                aborted = False

    if not completions:
        return (None, None, 'no non-aborted READ bit-cycle completion occurred in this trace')

    for row in completions:
        outputs = row.get('outputs', {})
        if outputs.get('idle') != 1:
            return (False, row.get('edge'), 'after the READ bit cycle completed, the FSM did not return to idle')
        if outputs.get('cmd_ack') != 1:
            return (False, row.get('edge'), 'after the READ bit cycle completed, cmd_ack was not asserted')

    return (True, completions[-1].get('edge'), 'each completed READ bit cycle returned to idle and asserted cmd_ack')

def decide(trace):
    activations = []
    for i in range(1, len(trace)):
        prev = trace[i - 1]
        row = trace[i]
        pin = row.get('inputs', {})
        prev_pin = prev.get('inputs', {})
        prev_out = prev.get('outputs', {})
        out = row.get('outputs', {})
        if pin.get('nReset') == 0 or pin.get('rst') == 1:
            continue
        if (prev_pin.get('cmd') == 8 or pin.get('cmd') == 8) and \
           prev_out.get('read_sequence') == 1 and out.get('read_sequence') == 0:
            activations.append(i)

    if not activations:
        return (None, None, 'the READ bit-cycle completion activation never occurred')

    for i in activations:
        completed = trace[i]
        completion_edge = completed.get('edge')
        idle_seen = False
        ack_seen = False
        voided = False

        for j in range(i, len(trace)):
            row = trace[j]
            inputs = row.get('inputs', {})
            outputs = row.get('outputs', {})
            if inputs.get('nReset') == 0 or inputs.get('rst') == 1:
                voided = True
                break
            if outputs.get('al') == 1:
                voided = True
                break
            if outputs.get('idle') == 1:
                idle_seen = True
            if outputs.get('cmd_ack') == 1:
                ack_seen = True
            if idle_seen and ack_seen:
                break

        if voided:
            continue
        if not idle_seen:
            return (False, completion_edge,
                    'after the READ bit cycle completed, the FSM did not return to idle')
        if not ack_seen:
            return (False, completion_edge,
                    'after the READ bit cycle completed, cmd_ack did not assert')

    return (True, trace[activations[-1]].get('edge'),
            'each completed READ bit cycle eventually returned the FSM to idle and asserted cmd_ack')

