def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, eventually, pulse, worst

    def _holds(row, cond):
        values = row.get('outputs', {})
        return all(values.get(port) == value for port, value in cond.items())

    def _any(conditions):
        return lambda row: any(_holds(row, cond) for cond in conditions)

    def _activation(row):
        # Use the declared phase probe rather than an invented cmd encoding.
        return (_holds(row, {'write_stable_high_phase': 1})
                and row.get('inputs', {}).get('ena') == 1)

    def _aborted(row):
        return _any([
            {'al': 1},
            {'nReset': 0},
            {'rst': 1},
        ])(row)

    windows = after(
        trace,
        _activation,
        until=_any([{'cmd_ack': 1}]),
        aborts=_aborted,
    )

    verdicts = []
    for w in windows:
        if w.value('scl_oen') != 1:
            verdicts.append((False, w.edge,
                             'SCL was not released high during the stable high phase'))
            continue

        verdicts.append(eventually(
            w,
            lambda r: r['outputs'].get('scl_oen') == 0,
            strong=True,
            after_activation=True,
        ))
        verdicts.append(eventually(
            w,
            lambda r: r['outputs'].get('idle') == 1,
            strong=True,
            after_activation=True,
        ))
        verdicts.append(eventually(
            w,
            lambda r: r['outputs'].get('cmd_ack') == 1,
            strong=True,
            after_activation=True,
        ))
        verdicts.append(pulse(
            w,
            'cmd_ack',
            width=1,
            active=1,
            after_activation=True,
        ))

    return worst(verdicts)

