def decide(trace):
    def probe(row, name, value=1):
        return row.get("outputs", {}).get(name) == value

    def qualified(row):
        return (
            row.get("inputs", {}).get("ena") == 1
            and probe(row, "write_sequence")
            and probe(row, "write_stable_high_phase")
        )

    def abort(row):
        return (
            row.get("inputs", {}).get("nReset") == 0
            or row.get("inputs", {}).get("rst") == 1
            or probe(row, "al")
        )

    windows = after(trace, qualified, until=TO_END, aborts=abort)
    scl_falls = edges(trace, "scl_oen", "fall")
    verdicts = []

    for window in windows:
        # The obligation says SCL is released during the stable high phase;
        # this is a level requirement, not a demand for a particular edge.
        verdicts.append(
            (True, window.edge, "scl_oen is released high during the WRITE stable high phase")
            if window.value("scl_oen") == 1
            else (False, window.edge, "scl_oen is not released high during the WRITE stable high phase")
        )

        # The later low phase is an action, so require the falling transition,
        # not merely a low level that may have existed before activation.
        verdicts.append(
            eventually(
                window,
                lambda row: row.get("edge") in scl_falls,
                after_activation=True,
                strong=True,
            )
        )

        verdicts.append(
            eventually(
                window,
                lambda row: probe(row, "idle"),
                after_activation=True,
                strong=True,
            )
        )

        # cmd_ack is explicitly a one-clock pulse in the obligation.  Using
        # held preserves the stated duration without inventing a response edge.
        verdicts.append(
            eventually(
                window,
                lambda row: (
                    row.get("outputs", {}).get("cmd_ack") == 1
                    and row.get("held") == 1
                ),
                after_activation=True,
                strong=True,
            )
        )

    return worst(verdicts)

