def decide(trace):
    def value(row, name, default=0):
        return row.get("outputs", {}).get(name, default)

    def activation(row):
        return (
            row.get("inputs", {}).get("cmd") == 4
            and row.get("inputs", {}).get("ena") == 1
            and value(row, "write_sequence") == 1
            and value(row, "write_stable_high_phase") == 1
        )

    def aborted(row):
        return (
            value(row, "al") == 1
            or row.get("inputs", {}).get("nReset") == 0
            or row.get("inputs", {}).get("rst") == 1
        )

