        trace,
        activation,
        until=lambda r: value(r, "cmd_ack") == 1,
        aborts=aborted,
    )
    verdicts = []

    for window in windows:
        rows = list(window.rows)
        start = window.edge
        later = [r for r in rows if r.get("edge") > start]

        release = None
        for i, row in enumerate(trace):
            if row.get("edge") <= start or i == 0:
                continue
            prev = trace[i - 1]
            if prev.get("edge") <= start:
                prev_value = value(prev, "scl_oen")
            else:
                prev_value = value(prev, "scl_oen")
            if prev_value != 1 and value(row, "scl_oen") == 1:
                if row.get("edge") <= (rows[-1].get("edge") if rows else row.get("edge")):
                    release = row
                    break

        if release is None:
            if rows and rows[-1].get("edge") == start:
                verdicts.append((None, start, "the WRITE stable-high completion window has not produced the SCL release yet"))
            else:
                verdicts.append((False, start, "SCL was not transitioned into the released high state during the WRITE stable-high phase"))
            continue

        release_edge = release.get("edge")
        pull_low = None
        for i, row in enumerate(trace):
            if row.get("edge") <= release_edge or i == 0:
                continue
            prev = trace[i - 1]
            if prev.get("edge") < release_edge:
                continue
            if value(prev, "scl_oen") != 0 and value(row, "scl_oen") == 0:
                pull_low = row
                break

        if pull_low is None:
            if value(rows[-1], "cmd_ack") != 1:
                verdicts.append((None, release_edge, "SCL was released, but the later pull-low and completion states are not present in the trace"))
            else:
                verdicts.append((False, rows[-1].get("edge"), "SCL was released but was not transitioned back to pulled low before completion"))
            continue

        low_edge = pull_low.get("edge")
        phase_rows = [
            r for r in rows
            if release_edge <= r.get("edge") < low_edge
            and value(r, "write_stable_high_phase") == 1
        ]
        if not phase_rows:
            verdicts.append((False, low_edge, "the stable high phase was not observed between SCL release and the following pull-low transition"))
            continue
        bad_phase = next((r for r in phase_rows if value(r, "sda_chk") != 1), None)
        if bad_phase is not None:
            verdicts.append((False, bad_phase.get("edge"), "SDA arbitration checking was not enabled during the stable high phase"))
            continue

        idle = next(
            (r for r in rows if r.get("edge") >= low_edge and value(r, "idle") == 1),
            None,
        )
        if idle is None:
            verdicts.append((False, low_edge, "the FSM did not return to idle after pulling SCL low"))
            continue

        ack = None
        for i, row in enumerate(trace):
            if row.get("edge") <= idle.get("edge") or i == 0:
                continue
            if value(trace[i - 1], "cmd_ack") == 0 and value(row, "cmd_ack") == 1:
                ack = row
