def decide(trace):
    from specflow.refmodel.temporal import TO_END, after, edges, eventually, pulse, worst

    sequence_probes = (
        'start_sequence',
        'stop_sequence',
        'read_sequence',
        'write_sequence',
    )

    def out(row, name):
        return row.get('outputs', {}).get(name)

    def inp(row, name):
        return row.get('inputs', {}).get(name)

    ended = {
        probe: edges(trace, probe, 'fall')
        for probe in sequence_probes
    }
    terminal_edges = set().union(*ended.values()) if ended else set()

    # A later sequence start bounds the completion indication to the
    # operation that ended at this terminal transition.
    starts = set().union(*(
        edges(trace, probe, 'rise') for probe in sequence_probes
    ))

    def opens(row):
        return (
            row.get('edge') in terminal_edges
            and inp(row, 'ena') == 1
            and inp(row, 'nReset') != 0
            and inp(row, 'rst') != 1
        )

    def closes(row):
        return row.get('edge') in starts

    aborts = lambda row: inp(row, 'nReset') == 0 or inp(row, 'rst') == 1

    windows = after(trace, opens, until=closes, aborts=aborts)
    if not windows:
        return (None, None, 'no completed START, STOP, READ, or WRITE sequence occurred in this trace')

