    def out(row, name, default=0):
        return row.get("outputs", {}).get(name, default)

    def rose(name):
        result = set()
        for i in range(1, len(trace)):
            if out(trace[i], name) == 1 and out(trace[i - 1], name) != 1:
                result.add(trace[i]["index"])
        return result

    def fell(name):
        result = set()
        for i in range(1, len(trace)):
            if out(trace[i], name) != 1 and out(trace[i - 1], name) == 1:
                result.add(trace[i]["index"])
        return result

